export const IR_RADIONAV_QUESTIONS: AirLawQuestion[] = [
  { id: "IRRN-001", sectionId: "C.2.5", question: "As an aeroplane approaches the runway while taxiing for departure, the flight crew observes two sets of yellow lines across the taxiway, one further away signed \"S2 CAT II/III\" and one closer signed \"S1\". Why is there a separate holding position for category II and III operations compared to all other operations, including CAT I?", optionA: "Since aeroplanes perform an autoland during CAT I operations the autopilot flies more accurately, so the CAT I position may be closer to the runway", optionB: "Because of the lower visibility during CAT II/III operations, the landing pilot(s) may mistake the lights from the waiting aircraft as runway lighting", optionC: "Aircraft must be kept further away during CAT II/III operations as arriving aeroplanes may land automatically and therefore require more space", optionD: "The landing minima for CAT II and III operations are lower and therefore require greater precision, and an aircraft waiting too close to the landing runway may affect the quality of the ILS signals", correctAnswer: "d", explanation: "CAT II/III minima are lower and demand precise ILS signals; a too-close waiting aircraft can disturb the ILS, so the holding point is set further back (clear of the ILS critical/sensitive area).", difficulty: "medium" },
  { id: "IRRN-002", sectionId: "C.2.5", question: "What is the difference between CAT II and CAT III ILS approaches?", optionA: "Only CAT III allows NO decision height", optionB: "Only CAT III requires a radio altimeter", optionC: "Only CAT III requires a runway visual range", optionD: "Only CAT II requires a runway visual range", correctAnswer: "a", explanation: "CAT III (notably IIIb/c) can be flown with no decision height, whereas CAT II always has a decision height.", difficulty: "medium" },
  { id: "IRRN-003", sectionId: "C.2.5", question: "ILS approaches are divided into Facility Performance Categories. Which of the following relates to Facility Performance Category II?", optionA: "It is an ILS which, with the aid of ancillary equipment when necessary, provides guidance from the coverage limit down to and along the runway", optionB: "Guidance from the coverage limit to the point at which the localiser course line intersects the ILS glide path at a height of 60 m (200 ft) or less above the horizontal plane containing the threshold", optionC: "Guidance from the coverage limit to the point at which the localiser course line intersects the ILS glide path at a height of 15 m (50 ft) or less above the horizontal plane containing the threshold", optionD: "Guidance from the coverage limit to the point at which the localiser course line intersects the ILS glide path at a height of 30 m (100 ft) or less above the horizontal plane containing the threshold", correctAnswer: "c", explanation: "Facility Performance Category II provides guidance down to 15 m (50 ft) above the threshold horizontal plane.", difficulty: "medium" },
  { id: "IRRN-004", sectionId: "C.2.5", question: "During ILS Category II and III operations, the pre take-off runway holding point is different to the holding point used in Category I operations in order to:", optionA: "Increase the distance from the runway of taxiing aircraft during low visibility, precision approach operations", optionB: "Prevent unacceptable interference of the ILS signal due to aircraft coming too near to the runway", optionC: "Increase aircraft separation in very reduced visibility conditions", optionD: "Move the holding point out of the ILS critical area as the holding is positioned within the ILS critical area during category I operations", correctAnswer: "b", explanation: "The CAT II/III holding point is set back to keep aircraft out of the ILS sensitive area and prevent unacceptable interference of the ILS signal.", difficulty: "medium" },
  { id: "IRRN-005", sectionId: "C.2.5", question: "ILS Multipath interference may be caused only by objects:", optionA: "Outside the ILS protected area", optionB: "In the ILS critical area", optionC: "Outside the ILS sensitive area", optionD: "In the ILS coverage area", correctAnswer: "d", explanation: "Reflecting objects within the ILS coverage area produce multipath interference.", difficulty: "medium" },
  { id: "IRRN-006", sectionId: "C.2.5", question: "At what distance from the end of the runway are you likely to find the outer marker?", optionA: "4 KM", optionB: "10 KM", optionC: "4 NM", optionD: "10 NM", correctAnswer: "c", explanation: "The outer marker is typically located about 4 NM from the runway threshold.", difficulty: "medium" },
  { id: "IRRN-007", sectionId: "C.2.5", question: "Full deflection on a glide slope indicator indicates that the aircraft is:", optionA: "1.25° above or below the correct glide path", optionB: "0.5° above or below the correct glide path", optionC: "2.5° above or below the correct glide path", optionD: "0.7° above or below the correct glide path", correctAnswer: "d", explanation: "Full-scale glide slope deflection corresponds to about 0.7° from the glide path.", difficulty: "medium" },
  { id: "IRRN-008", sectionId: "C.2.5", question: "There are several facility performance categories for ILS approaches. Which option describes the facility performance category II?", optionA: "Guidance from the coverage limit to the point at which the localiser course line intersects the ILS glide path at a height of 60 m (200 ft) or less above the horizontal plane containing the threshold", optionB: "It provides guidance from the coverage limit to the point at which the localiser course line intersects the ILS glide path at a height of 30 m (100 ft) or less above the threshold", optionC: "Guidance from the coverage limit to the point at which the localiser course line intersects the ILS glide path at a height of 15 m (50 ft) or less above the horizontal plane containing the threshold", optionD: "It is an ILS which, with the aid of ancillary equipment when necessary, provides guidance from the coverage limit down to and along the runway", correctAnswer: "c", explanation: "Category II provides guidance down to 15 m (50 ft) above the threshold horizontal plane.", difficulty: "medium" },
  { id: "IRRN-009", sectionId: "C.2.5", question: "A Microwave Landing System (MLS) offers:", optionA: "4D representation of 4D curved approach", optionB: "3D representation of 4D approach", optionC: "2D representation of a 3D segmented approach", optionD: "2D representation of 2D straight-in approach", correctAnswer: "c", explanation: "MLS supports a 2D representation of a 3D segmented (curved/segmented) approach.", difficulty: "medium" },
  { id: "IRRN-010", sectionId: "C.2.3", question: "An aircraft is flying at low altitude above uneven, mountainous terrain and man-made obstructions, towards a VOR selected on the OBS/CDI. The CDI needle does side motions and fluctuates from time to time, while the aircraft is constantly and accurately tracking inbound. What is this effect called?", optionA: "Night effect", optionB: "Quadrantal error", optionC: "Scalloping", optionD: "Defective CDI", correctAnswer: "c", explanation: "VOR scalloping is the momentary needle fluctuation caused by terrain/obstruction reflections of the VOR signal.", difficulty: "medium" },
  { id: "IRRN-011", sectionId: "C.2.5", question: "The audio frequency modulation of the outer marker shall be keyed as follows:", optionA: "3 dashes, 3 dots and 3 dashes per second continuously", optionB: "2 dashes per second continuously", optionC: "6 dots per second continuously", optionD: "a continuous series of alternate dots and dashes", correctAnswer: "b", explanation: "The outer marker (400 Hz) is keyed as 2 dashes per second continuously.", difficulty: "medium" },
  { id: "IRRN-012", sectionId: "C.2.5", question: "The audio frequency modulation of the middle marker shall be keyed as follows:", optionA: "3 dashes, 3 dots and 3 dashes per second continuously", optionB: "a continuous series of alternate dots and dashes, the dashes keyed at the rate of 2 dashes per second, and the dots at the rate of 6 dots per second", optionC: "2 dashes per second continuously", optionD: "6 dots per second continuously", correctAnswer: "b", explanation: "The middle marker (1300 Hz) is keyed as alternating dots and dashes (2 dashes/sec, 6 dots/sec).", difficulty: "medium" },
  { id: "IRRN-013", sectionId: "C.2.5", question: "The audio frequency modulation of the inner marker (if available) shall be keyed as follows:", optionA: "2 dashes per second continuously", optionB: "6 dots per second continuously", optionC: "3 dashes, 3 dots and 3 dashes per second continuously", optionD: "a continuous series of alternate dots and dashes", correctAnswer: "b", explanation: "The inner marker (3000 Hz) is keyed as 6 dots per second continuously.", difficulty: "medium" },
  { id: "IRRN-014", sectionId: "C.2.5", question: "The ILS marker identified visually by an amber light flashing is the:", optionA: "Outer marker", optionB: "Middle marker", optionC: "Locator", optionD: "Inner marker", correctAnswer: "b", explanation: "The middle marker is shown by an amber marker light.", difficulty: "medium" },
  { id: "IRRN-015", sectionId: "C.2.5", question: "The ILS marker identified visually by a white light flashing is the:", optionA: "middle marker", optionB: "inner marker", optionC: "locator", optionD: "outer marker", correctAnswer: "b", explanation: "The inner marker is shown by a white marker light.", difficulty: "medium" },
  { id: "IRRN-016", sectionId: "C.2.5", question: "The ILS marker identified visually by a blue flashing light is the:", optionA: "Middle marker", optionB: "Inner marker", optionC: "Outer marker", optionD: "Locator", correctAnswer: "c", explanation: "The outer marker is shown by a blue marker light.", difficulty: "medium" },
  { id: "IRRN-017", sectionId: "C.2.5", question: "What is the preferred ILS glide path for a precision approach?", optionA: "3%", optionB: "2.5%", optionC: "3 degrees", optionD: "5 degrees", correctAnswer: "c", explanation: "The optimum/standard ILS glide path angle is 3 degrees.", difficulty: "medium" },
  { id: "IRRN-018", sectionId: "C.2.5", question: "In the final phase of a flight, the aircraft is awaiting 'capture' of the ILS localiser with the Flight Director active. When the localiser has been captured the amber 'LOC' indication will:", optionA: "change to red", optionB: "change to green", optionC: "extinguish, and no further indication is given", optionD: "start flashing for 10 seconds and then extinguish", correctAnswer: "b", explanation: "On capture, the armed (amber) LOC annunciation changes to green (engaged/captured).", difficulty: "medium" },
  { id: "IRRN-019", sectionId: "C.2.5", question: "ILS produces:", optionA: "a radiation pattern which is amplitude modulated by a 90Hz and a 150Hz signal", optionB: "two lobes modulated in frequency by a 90Hz and a 150Hz signal", optionC: "a 90 Hz lobe and a 150 Hz lobe which are amplitude modulated by the VHF frequency of the ILS", optionD: "a radiation pattern which is amplitude modulated by the VHF frequency of the ILS", correctAnswer: "a", explanation: "The ILS localiser/glide path radiate overlapping lobes amplitude-modulated at 90 Hz and 150 Hz.", difficulty: "medium" },
  { id: "IRRN-020", sectionId: "C.2.5", question: "The heading rose of an HSI is frozen on 200°. Lined up on the ILS of runway 25, the localizer needle will be:", optionA: "left of centre", optionB: "right of centre", optionC: "centered", optionD: "centered with the fail flag showing", correctAnswer: "c", explanation: "The ILS localiser deviation is independent of the HSI compass card; lined up on the localiser the needle is centred regardless of a frozen heading.", difficulty: "medium" },
  { id: "IRRN-021", sectionId: "C.2.5", question: "Find the correct frequency band of an ILS glide slope transmission:", optionA: "LF", optionB: "SHF", optionC: "UHF", optionD: "VHF", correctAnswer: "c", explanation: "The ILS glide path operates in the UHF band (329.15–335 MHz); the localiser is VHF.", difficulty: "medium" },
  { id: "IRRN-022", sectionId: "C.2.5", question: "Assuming a five dot display on either side of the CDI on the ILS localizer cockpit display, what does each of the dots represent approximately?", optionA: "2.5 degrees", optionB: "0.5 degrees", optionC: "2.0 degrees", optionD: "1.5 degrees", correctAnswer: "b", explanation: "Full-scale localiser deflection (~2.5°) over five dots gives about 0.5° per dot.", difficulty: "medium" },
  { id: "IRRN-023", sectionId: "C.2.5", question: "Assuming a five dot display on either side of the ILS localizer cockpit display, what is the angular displacement of the aircraft from the localizer centre line when the CDI is deflected 2 dots to the right?", optionA: "2.0° to the left", optionB: "1.0° to the left", optionC: "2.0° to the right", optionD: "1.0° to the right", correctAnswer: "b", explanation: "2 dots × 0.5°/dot = 1.0°; a right-deflected needle means the aircraft is to the left of the centre line.", difficulty: "medium" },
  { id: "IRRN-024", sectionId: "C.2.5", question: "An area where the parking and/or movement of vehicles, including aircraft, is controlled to prevent the possibility of unacceptable interference to the ILS signal during ILS operations is called:", optionA: "ILS-shutdown area", optionB: "ILS-sensitive area", optionC: "ILS-larger sensitive area", optionD: "ILS-critical area", correctAnswer: "b", explanation: "The ILS sensitive area is where vehicle/aircraft movement is controlled to avoid unacceptable ILS signal interference.", difficulty: "medium" },
  { id: "IRRN-025", sectionId: "C.2.5", question: "An area of defined dimensions around the LOC and GP antennas where vehicles, including aircraft, are excluded during all ILS operations is called:", optionA: "ILS-shutdown area", optionB: "ILS-sensitive area", optionC: "ILS-critical area", optionD: "ILS-larger sensitive area", correctAnswer: "c", explanation: "The ILS critical area is the protected area around the antennas from which all vehicles/aircraft are excluded during ILS operations.", difficulty: "medium" },
  { id: "IRRN-026", sectionId: "C.2.5", question: "The localiser transmitters operate in a frequency band between:", optionA: "111.975 MHz and 117.975 MHz", optionB: "329.15 MHz and 335 MHz", optionC: "108 MHz and 117.975 MHz", optionD: "108 MHz and 111.975 MHz", correctAnswer: "d", explanation: "The ILS localiser operates in the VHF band 108–111.975 MHz (odd-tenth frequencies).", difficulty: "medium" },
  { id: "IRRN-027", sectionId: "C.2.5", question: "Reflections from large objects within the ILS coverage area may cause?", optionA: "Single path interference", optionB: "Doppler errors", optionC: "Static noise", optionD: "Multipath interference", correctAnswer: "d", explanation: "Reflections from large objects in the coverage area create multipath interference (bending/scalloping of the ILS beam).", difficulty: "medium" },
  { id: "IRRN-028", sectionId: "C.2.5", question: "Which of the following is correct regarding false beams on a glide path?", optionA: "False beams will only be found more than 10 degrees", optionB: "False beams will only be found below the correct glide path", optionC: "False beams are only present when flying a back beam ILS", optionD: "False beams will only be found above the correct glide path", correctAnswer: "d", explanation: "Glide path false beams occur only above the true 3° glide path (e.g. at ~6°, 9°), never below it.", difficulty: "medium" },
  { id: "IRRN-029", sectionId: "C.2.5", question: "The visual and aural indications of the ILS outer marker are:", optionA: "An amber light and alternate dots and dashes of a 1300 Hz modulated tone", optionB: "A blue light and 2 dashes per second of a 1300 Hz modulated tone", optionC: "A white light and 6 dots per second of a 30 Hz modulated tone", optionD: "A blue light and 2 dashes per second of 400 Hz modulated tone", correctAnswer: "d", explanation: "The outer marker: blue light, 2 dashes per second, 400 Hz tone.", difficulty: "medium" },
  { id: "IRRN-030", sectionId: "C.2.5", question: "Which of the following is an ILS localiser frequency?", optionA: "110.20 MHz", optionB: "108.25 MHz", optionC: "112.10 MHz", optionD: "109.15 MHz", correctAnswer: "d", explanation: "Localiser frequencies lie 108–111.975 MHz on odd-tenth 50 kHz channels; 109.15 MHz is a valid localiser frequency.", difficulty: "medium" },
  { id: "IRRN-031", sectionId: "C.2.5", question: "Which answer states the typical distances along the centreline of the runway of the various ILS components?", optionA: "Localizer transmitter: 300 m behind end of runway; Glide path transmitter: 300 m behind threshold; Middle Marker: 1.5 NM from threshold; Outer Marker: 10 NM from threshold", optionB: "Localizer transmitter: 100 m behind end of runway; Glide path transmitter: 100 m behind threshold; Middle Marker: 1000 m from threshold; Outer Marker: 4 NM from threshold", optionC: "Localizer transmitter: 100 m behind end of runway; Glide path transmitter: 100 m behind threshold; Middle Marker: 1.5 NM from threshold; Outer Marker: 10 NM from threshold", optionD: "Localizer transmitter: 300 m behind end of runway; Glide path transmitter: 300 m behind threshold; Middle Marker: 1000 m from threshold; Outer Marker: 4 NM from threshold", correctAnswer: "d", explanation: "Typical layout: localiser ~300 m past the stop end, glide path ~300 m behind threshold, middle marker ~1000 m and outer marker ~4 NM from threshold.", difficulty: "medium" },
  { id: "IRRN-032", sectionId: "C.2.5", question: "On final on an ILS approach, you are flying overhead the outer marker. You can expect to be at:", optionA: "4 NM from the threshold", optionB: "1 NM from the threshold", optionC: "10 NM from the threshold", optionD: "25 NM from the threshold", correctAnswer: "a", explanation: "The outer marker is typically about 4 NM from the threshold.", difficulty: "medium" },
  { id: "IRRN-033", sectionId: "C.2.5", question: "An ILS Glidepath provides azimuth coverage (i)….. each side of the localizer centre line to a distance of (ii)…. nm minimum from the threshold.", optionA: "(i) 25; (ii) 17", optionB: "(i) 7; (ii) 10", optionC: "(i) 5; (ii) 18", optionD: "(i) 8; (ii) 10", correctAnswer: "d", explanation: "ILS coverage is provided ±8° of the centre line out to at least 10 NM.", difficulty: "medium" },
  { id: "IRRN-034", sectionId: "C.2.5", question: "The coverage of the ILS glideslope with respect to the localizer centreline is:", optionA: "± 35° to 17 nm", optionB: "± 10° to 8 nm", optionC: "± 10° to 25 nm", optionD: "± 8° to 10 nm", correctAnswer: "d", explanation: "ILS coverage extends ±8° of the localiser centre line out to about 10 NM.", difficulty: "medium" },
  { id: "IRRN-035", sectionId: "C.2.5", question: "What is measured in order to establish aircraft position in relation to the localizer beam on an ILS?", optionA: "The bearing to the localizer antenna found by means of a loop antenna", optionB: "The difference in phase between the 90 Hz modulation and the 150 Hz modulation", optionC: "The difference in time between the 90 Hz modulation and the 150 Hz modulation", optionD: "The difference in depth between the 90 Hz modulation and the 150 Hz modulation", correctAnswer: "d", explanation: "Localiser position is derived from the Difference in Depth of Modulation (DDM) between the 90 Hz and 150 Hz signals.", difficulty: "medium" },
  { id: "IRRN-036", sectionId: "C.2.5", question: "On a localizer the modulations are at 150 Hz and 90 Hz. Which of the following statements is correct?", optionA: "The 90 Hz modulation predominates to the right of the centre line", optionB: "If the 150 Hz modulations predominates, the needle on the CDI moves to the right of centre", optionC: "The 150 Hz modulation predominates to the right of the centre line", optionD: "When both modulations are received, the aeroplane will be on the centerline", correctAnswer: "c", explanation: "On the localiser the 150 Hz signal predominates on the right of the centre line (90 Hz on the left).", difficulty: "medium" },
  { id: "IRRN-037", sectionId: "C.2.5", question: "An aircraft tracking to intercept the ILS localizer inbound on the approach side, outside the published ILS coverage angle:", optionA: "can expect signals to give correct indications", optionB: "may receive false course indications", optionC: "will not normally receive signals", optionD: "will receive signals without identification coding", correctAnswer: "b", explanation: "Outside the published coverage the localiser can present false courses; only within coverage are indications reliable.", difficulty: "medium" },
  { id: "IRRN-038", sectionId: "C.2.5", question: "The amplitude modulation and the color of an outer marker (OM) is:", optionA: "400 Hz, amber", optionB: "400 Hz, blue", optionC: "1300 Hz, blue", optionD: "3000 Hz, blue", correctAnswer: "b", explanation: "The outer marker is modulated at 400 Hz and shown by a blue light.", difficulty: "medium" },
  { id: "IRRN-039", sectionId: "C.2.5", question: "In which frequency band does an ILS glide slope transmit?", optionA: "UHF", optionB: "EHF", optionC: "SHF", optionD: "VHF", correctAnswer: "a", explanation: "The ILS glide path transmits in the UHF band (329.15–335 MHz).", difficulty: "medium" },
  { id: "IRRN-040", sectionId: "C.2.5", question: "The type of modulation used for the ILS frequency carrier is:", optionA: "phase modulation", optionB: "frequency modulation", optionC: "amplitude modulation", optionD: "dual modulation", correctAnswer: "c", explanation: "The ILS localiser/glide path carriers are amplitude modulated (by the 90 Hz and 150 Hz tones).", difficulty: "medium" },
  { id: "IRRN-041", sectionId: "C.2.5", question: "On an ILS approach, when flying overhead the outer marker the color of the flashing light will be:", optionA: "white", optionB: "green", optionC: "blue", optionD: "amber", correctAnswer: "c", explanation: "The outer marker is indicated by a blue flashing light.", difficulty: "medium" },
  { id: "IRRN-042", sectionId: "C.2.1", question: "In ISA conditions, what is the maximum theoretical range at which an aircraft at FL80 can expect to obtain bearings from a ground VDF facility sited 325 ft above MSL?", optionA: "158 NM", optionB: "107 NM", optionC: "132 NM", optionD: "114 NM", correctAnswer: "c", explanation: "VHF is line-of-sight: range ≈ 1.23(√8000 + √325) ≈ 132 NM.", difficulty: "medium" },
  { id: "IRRN-043", sectionId: "C.2.1", question: "What is the minimum level (ISA conditions) that an aircraft at a range of 111 NM must fly in order to contact the tower on R/T for a VDF bearing from an airport sited 169 ft above MSL?", optionA: "FL10", optionB: "FL80", optionC: "FL60", optionD: "FL50", correctAnswer: "c", explanation: "For line-of-sight to 111 NM from a 169 ft station the aircraft must be at roughly FL60.", difficulty: "hard" },
  { id: "IRRN-044", sectionId: "C.2.1", question: "One of the uses of the VDF service is providing aircraft with:", optionA: "ground speed", optionB: "homing", optionC: "heading", optionD: "altitude", correctAnswer: "b", explanation: "VDF gives the bearing to the station, allowing the aircraft to home to the airfield.", difficulty: "easy" },
  { id: "IRRN-045", sectionId: "C.2.1", question: "The range at which you can obtain a VDF bearing can be influenced by:", optionA: "height of aircraft", optionB: "time of day", optionC: "type of surface", optionD: "intensity of ionization", correctAnswer: "a", explanation: "VDF (VHF) is line-of-sight, so range increases with aircraft height.", difficulty: "medium" },
  { id: "IRRN-046", sectionId: "C.2.1", question: "Which of the following affects VDF range?", optionA: "Coastal refraction", optionB: "Strength of the pilot's voice when transmitting", optionC: "Sky wave propagation", optionD: "The height of the transmitter and of the receiver", correctAnswer: "d", explanation: "As a line-of-sight VHF service, VDF range depends on the heights of both transmitter and receiver.", difficulty: "medium" },
  { id: "IRRN-047", sectionId: "C.2.1", question: "What airborne equipment, if any, is required to be fitted in order that a VDF let-down may be flown?", optionA: "none", optionB: "VOR/DME", optionC: "VHF radio", optionD: "VOR", correctAnswer: "c", explanation: "VDF works from the aircraft's ordinary VHF R/T transmissions; only a VHF radio is required.", difficulty: "medium" },
  { id: "IRRN-048", sectionId: "C.2.1", question: "The VDF Homer service provides:", optionA: "A QGH procedure to transiting aeroplanes", optionB: "Bearings which may be affected by synchronous transmissions", optionC: "Bearings which will normally be within ±5° accuracy to a range of 200NM", optionD: "Accurate bearings on demand", correctAnswer: "c", explanation: "A Class C VDF (homer) bearing is accurate to within ±5° (out to line-of-sight range).", difficulty: "medium" },
  { id: "IRRN-049", sectionId: "C.2.1", question: "Ground direction finding is provided on a particular lower frequency in the following VHF frequency range:", optionA: "118.0MHz - 139.975MHz", optionB: "118.0MHz - 135.975MHz", optionC: "960MHz – 1215MHz", optionD: "108MHz – 117.95MHz", correctAnswer: "b", explanation: "VDF uses the VHF communications band 118.0–135.975 MHz.", difficulty: "medium" },
  { id: "IRRN-050", sectionId: "C.2.1", question: "What is the effect of multipath signals (coming from the same aircraft) at the Ground VHF Direction Finder station?", optionA: "They may result in bearing errors", optionB: "Regardless of the difference in distance travelled by these signals, it results in the extinction of the signals at the Ground VHF Direction Finder station", optionC: "It reduces the range at which the Ground VHF Direction Finder station receives signals from the aircraft", optionD: "It may result in an increase of the distance at which the Ground VHF Direction Finder station receives signals from the aircraft, if the Ground Station is situated in the skip zone", correctAnswer: "a", explanation: "Multipath (reflected) signals reaching the ground DF antenna produce bearing errors.", difficulty: "medium" },
  { id: "IRRN-051", sectionId: "C.2.1", question: "What is the maximum range at which a VDF station at 325 ft can provide a service to an aircraft at FL080?", optionA: "134 nm", optionB: "91 nm", optionC: "114 nm", optionD: "107 nm", correctAnswer: "a", explanation: "Line-of-sight range ≈ 1.25(√8000 + √325) ≈ 134 NM.", difficulty: "medium" },
  { id: "IRRN-052", sectionId: "C.2.3", question: "Which of the following statements is true regarding the working principle of VOR? (1) To determine the VOR radial, the aircraft VOR receiver measures the phase difference between the reference phase and the variable phase signals. (2) To determine the VOR radial, the aircraft VOR receiver measures the time difference between the reception of the variable signal and the reference signal.", optionA: "I is incorrect, II is correct", optionB: "I is correct, II is correct", optionC: "I is incorrect, II is incorrect", optionD: "I is correct, II is incorrect", correctAnswer: "d", explanation: "VOR radial is derived from the phase difference between reference and variable phases (statement 1 correct; statement 2 false).", difficulty: "medium" },
  { id: "IRRN-053", sectionId: "C.2.2", question: "Fading (LF/MF) can happen:", optionA: "only at night", optionB: "from the beginning of evening twilight until the end of morning twilight", optionC: "at any time during the day or night", optionD: "only during daytime", correctAnswer: "b", explanation: "LF/MF sky-wave interference (night effect) occurs from dusk to dawn (evening to morning twilight).", difficulty: "medium" },
  { id: "IRRN-054", sectionId: "C.2.2", question: "Which one of the statements below concerning Mountain Effect is correct?", optionA: "Mountain Effect will be compensated for by the receiver", optionB: "Mountain Effect does not occur at low altitudes", optionC: "Mountain Effect occurs only on NDB bearings", optionD: "Mountain Effect may occur on NDB and VOR bearings", correctAnswer: "d", explanation: "Terrain reflections (mountain effect) can corrupt both NDB (ADF) and VOR bearings.", difficulty: "medium" },
  { id: "IRRN-055", sectionId: "C.2.2", question: "The definition of the term QDR is:", optionA: "The true bearing to the station", optionB: "The magnetic bearing to the station", optionC: "The magnetic bearing from the station", optionD: "The true bearing from the station", correctAnswer: "c", explanation: "QDR is the magnetic bearing FROM the station (the radial); QDM is the magnetic bearing TO the station.", difficulty: "medium" },
  { id: "IRRN-056", sectionId: "C.2.5", question: "Which of the following radio aids use the VHF band? (1) Locator (2) Localizer (3) Outer Marker (4) Glide path.", optionA: "2 and 3", optionB: "2 and 4", optionC: "1, 2 and 3", optionD: "1 and 4", correctAnswer: "a", explanation: "The localiser (VHF) and the marker beacons (75 MHz, VHF) use the VHF band; the locator is LF/MF and the glide path is UHF.", difficulty: "medium" },
  { id: "IRRN-057", sectionId: "C.2.2", question: "Diffraction is the process by which:", optionA: "radio waves travel over and around obstacles", optionB: "a direct wave is bent around the form of the earth", optionC: "a ground wave is attenuated over rough ground", optionD: "a space wave penetrates the ionosphere", correctAnswer: "a", explanation: "Diffraction is the bending of radio waves over and around obstacles.", difficulty: "medium" },
  { id: "IRRN-058", sectionId: "C.2.2", question: "Which of the following statements is correct regarding the mountain effect as regards radio wave propagation?", optionA: "it can be caused by refraction of an NDB signal changing the path of the radio waves", optionB: "it can be caused by refraction of a VOR signal bending the path of the radio waves", optionC: "it prevents an aircraft at low altitude receiving VOR signals due to mountains blocking the radio waves", optionD: "it can be caused by diffraction of an NDB signal bending the path of the radio waves", correctAnswer: "d", explanation: "Mountain effect is caused by diffraction/reflection of the NDB signal bending its path, giving false bearings.", difficulty: "medium" },
  { id: "IRRN-059", sectionId: "C.2.2", question: "The radio communications equipment required shall provide communications on:", optionA: "The local rescue services frequency", optionB: "121.5 MHz", optionC: "112.5 MHz", optionD: "406 MHz", correctAnswer: "b", explanation: "121.5 MHz is the international VHF aeronautical emergency frequency the radio must be able to work.", difficulty: "easy" },
  { id: "IRRN-060", sectionId: "C.2.2", question: "The gain of an aerial is a measure of its ability to:", optionA: "Focus power", optionB: "Transmit intelligence", optionC: "Overcome transmitter line resistance", optionD: "Compensate for attenuation", correctAnswer: "a", explanation: "Aerial gain is the ability to focus/concentrate radiated power in a preferred direction.", difficulty: "medium" },
  { id: "IRRN-061", sectionId: "C.2.3", question: "The VHF Omnirange (VOR) uses the following wavelengths:", optionA: "metric", optionB: "hectometric", optionC: "centimetric", optionD: "decimetric", correctAnswer: "a", explanation: "VOR operates in the VHF band (108–117.975 MHz), which is metric wavelengths.", difficulty: "medium" },
  { id: "IRRN-062", sectionId: "C.2.2", question: "To hear the IDENT, a pilot has to:", optionA: "turn off the ADF", optionB: "select BFO OFF for NDBs using NON A1A", optionC: "selected BFO ON for NDBs using NON A2A", optionD: "select BFO ON for NDBs using NON A1A", correctAnswer: "d", explanation: "A NON/A1A NDB has an unmodulated carrier, so the BFO must be ON to make the ident audible.", difficulty: "medium" },
  { id: "IRRN-063", sectionId: "C.2.2", question: "You have entered the holding race track pattern via a Sector 1 entry and the holding fix is an NDB. Having joined the hold, flown outbound and then subsequently turned right onto the inbound leg approaching the beacon, how will you know when to initiate the next right turn outbound?", optionA: "The indicator will go from full left deflection to full right deflection when passing the fix", optionB: "The head of the needle will be pointing 360 degrees and will turn 180 degrees when past it", optionC: "The TO indication will become a FROM indication after passing the fix", optionD: "The head of the needle will be pointing away from the fix and the needle will turn 180 degrees when past it", correctAnswer: "b", explanation: "Tracking inbound to the NDB the needle head points to the top (360 rel); station passage swings it through 180°.", difficulty: "hard" },
  { id: "IRRN-064", sectionId: "C.2.2", question: "ICAO Doc 8168 describes how all procedures depict tracks and that pilots should attempt to maintain the track by applying corrections to heading for known wind. What are the implications of this statement for a pilot tracking to and from an NDB regardless of instrument type?", optionA: "The head or tail of the needle may point slightly left or right of the top of the instrument when maintaining the appropriate QDM or QDR", optionB: "Once the aircraft is established on the depicted track the head or tail of the needle will point straight up on the instrument regardless of wind conditions", optionC: "The head of the needle will be pointing at 360 when the aircraft is established on the inbound or outbound track", optionD: "The relative bearing will be equal to the wind correction angle required to maintain the depicted track towards or away from the NDB", correctAnswer: "a", explanation: "With a drift correction applied, the needle sits slightly off the top while the correct QDM/QDR track is maintained.", difficulty: "hard" },
  { id: "IRRN-065", sectionId: "C.2.2", question: "An RMI compass card has stuck at 090 degrees. The arrow of the needle points to 225 degrees. What is the Relative Bearing of the NDB?", optionA: "135 degrees", optionB: "180 degrees", optionC: "045 degrees", optionD: "315 degrees", correctAnswer: "a", explanation: "Relative bearing = RMI reading − heading = 225 − 090 = 135°.", difficulty: "medium" },
  { id: "IRRN-066", sectionId: "C.2.2", question: "ADF is the abbreviation for:", optionA: "Aircraft Directional finder", optionB: "Aircraft Direction Finding", optionC: "Automatic Direction Finder", optionD: "Automatic Detection Finding", correctAnswer: "c", explanation: "ADF stands for Automatic Direction Finder.", difficulty: "easy" },
  { id: "IRRN-067", sectionId: "C.2.2", question: "Under what circumstances would an ADF bearing be affected by dip error?", optionA: "the aircraft flying at a low level in a mountainous area", optionB: "the NDB being on a bearing at 45° to the aircraft's longitudinal axis", optionC: "the aircraft either banking or accelerating", optionD: "the aircraft banking", correctAnswer: "d", explanation: "ADF dip error arises when the aircraft is banked (the loop antenna tilts).", difficulty: "medium" },
  { id: "IRRN-068", sectionId: "C.2.2", question: "The accuracy the pilot has to fly the required bearing in order to be considered established during an NDB approach according to ICAO DOC 8168 is within plus or minus:", optionA: "7.5°", optionB: "2.5°", optionC: "5°", optionD: "2°", correctAnswer: "c", explanation: "ICAO Doc 8168 requires the ADF track to be within ±5° to be considered established.", difficulty: "medium" },
  { id: "IRRN-069", sectionId: "C.2.2", question: "The function of the BFO (Beat Frequency Oscillator) is:", optionA: "to make the modulating tone audible in order to identify NON/A1A modulated NDBs", optionB: "to make the carrier wave audible in order to identify A2A modulated NDBs", optionC: "to make the carrier wave audible in order to identify NON/A1A modulated NDBs", optionD: "to make the modulating tone audible in order to identify A2A modulated NDBs", correctAnswer: "c", explanation: "The BFO beats against the unmodulated NON/A1A carrier to produce an audible ident tone.", difficulty: "medium" },
  { id: "IRRN-070", sectionId: "C.2.2", question: "Which description is relevant for a locator beacon? The locator beacon is:", optionA: "An LF NDB, in the past often used for ocean crossings, to locate the aircraft's position, it has a range of 150 NM to 300 NM", optionB: "An HF VOR used as an aid for military aircraft, it has a line-of-sight range of up to 200 NM", optionC: "A VHF beacon used for lateral navigation during an ILS approach to the runway, it has a range up to 25 NM", optionD: "An LF/MF NDB used as an aid for the final approach, it has a range of 10 NM to 25 NM", correctAnswer: "d", explanation: "A locator is a low-power LF/MF NDB (often co-located with an ILS marker) used for the final approach, range ~10–25 NM.", difficulty: "medium" },
  { id: "IRRN-071", sectionId: "C.2.2", question: "Which of the following transmissions can be received by an ADF?", optionA: "A VDF call for bearing", optionB: "The transmission of a VOLMET", optionC: "The transmission of an ATIS", optionD: "A commercial radio station transmitting in the LF/MF band", correctAnswer: "d", explanation: "An ADF tunes LF/MF; it can receive a commercial LF/MF broadcast station.", difficulty: "medium" },
  { id: "IRRN-072", sectionId: "C.2.2", question: "When an NDB fails which kind of warning is visible in the cockpit?", optionA: "On a Radio Magnetic indicator: a flag alarm", optionB: "There is no warning", optionC: "On a moving card ADF: a red button", optionD: "On a digital navigation display: the acronym 'NDB' in red", correctAnswer: "b", explanation: "The ADF gives no failure flag; a failed NDB simply leaves the needle giving no valid indication with no warning.", difficulty: "medium" },
  { id: "IRRN-073", sectionId: "C.2.2", question: "Which of the following is the ICAO allocated frequency band for ADF receivers?", optionA: "255 – 455 kHz", optionB: "200 – 2000 kHz", optionC: "300 – 3000 kHz", optionD: "190 – 1750 kHz", correctAnswer: "d", explanation: "ICAO allocates 190–1750 kHz for ADF/NDB.", difficulty: "medium" },
  { id: "IRRN-074", sectionId: "C.2.2", question: "Concerning ADF and NDB:", optionA: "NDB is a locator and ADF is an en route nav-aid", optionB: "ADF is a ground equipment and NDB can be a ground equipment or an airborne equipment", optionC: "ADF is a civilian equipment whereas NDB is a military equipment used by civilians too", optionD: "NDB is a ground equipment, and ADF is an airborne equipment", correctAnswer: "d", explanation: "The NDB is the ground transmitter; the ADF is the airborne receiver.", difficulty: "medium" },
  { id: "IRRN-075", sectionId: "C.2.2", question: "The main factor that limits the range of an NDB is:", optionA: "the transmitted power", optionB: "all of the above", optionC: "the aircraft height", optionD: "the terrain", correctAnswer: "a", explanation: "NDB range is primarily limited by the transmitter's power (surface-wave attenuation).", difficulty: "medium" },
  { id: "IRRN-076", sectionId: "C.2.2", question: "You have to consider the shoreline/coastal effect especially at which radio navigation facility?", optionA: "VOR", optionB: "Terminal area surveillance radar", optionC: "EHF-COM", optionD: "NDB", correctAnswer: "d", explanation: "Coastal refraction (shoreline effect) bends LF/MF NDB bearings crossing a coastline.", difficulty: "medium" },
  { id: "IRRN-077", sectionId: "C.2.2", question: "Which of the following is the correct frequency band, propagation path, and frequency range for an NDB?", optionA: "LF and MF, surface waves, 190 kHz to 1750 kHz", optionB: "VHF, ground waves, 108 MHz to 117.975 MHz", optionC: "only MF, surface waves, 300 kHz to 1750 kHz", optionD: "UHF, space waves, 329.15 MHz to 335 MHz", correctAnswer: "a", explanation: "NDBs work on LF/MF surface waves, 190–1750 kHz.", difficulty: "medium" },
  { id: "IRRN-078", sectionId: "C.2.2", question: "In order to identify an NDB the BFO:", optionA: "Is automatically activated on modern aircraft, when necessary", optionB: "Should be switched off with an NON/A1A transmission", optionC: "Should be switched on when receiving a Locator transmission", optionD: "Should be switched off with an NON/A2A transmission", correctAnswer: "a", explanation: "On modern receivers the BFO is engaged automatically when required to identify a NON/A1A NDB.", difficulty: "medium" },
  { id: "IRRN-079", sectionId: "C.2.2", question: "Night Effect in an ADF may cause:", optionA: "No bearing error because of the built-in compensator unit", optionB: "Fluctuating indications of the needle on the RMI", optionC: "A constant error in the indicated bearing", optionD: "Noise in the received EM-wave, which hardly will be noticed by the pilot looking at the RMI", correctAnswer: "b", explanation: "Night effect (sky-wave contamination) makes the ADF needle fluctuate/wander on the RMI.", difficulty: "medium" },
  { id: "IRRN-080", sectionId: "C.2.2", question: "A cumulonimbus cloud in the vicinity of an aeroplane can cause certain navigation systems to give false indications. This is particularly true of the:", optionA: "VOR", optionB: "weather radar", optionC: "ADF", optionD: "DME", correctAnswer: "c", explanation: "Lightning/electrical activity in a CB attracts the ADF needle, giving false bearings (thunderstorm effect).", difficulty: "medium" },
  { id: "IRRN-081", sectionId: "C.2.2", question: "When identifying an NDB (NON A1A) it is necessary to:", optionA: "Turn the ANT off", optionB: "Turn the BFO off", optionC: "Turn the ANT on", optionD: "Turn the BFO on", correctAnswer: "d", explanation: "A NON/A1A NDB has no modulation, so the BFO must be on to produce an audible ident.", difficulty: "medium" },
  { id: "IRRN-082", sectionId: "C.2.2", question: "An RMI indicates aircraft heading. To convert the RMI bearings of NDB's and VOR's to true bearings, the correct combination for the application of magnetic variation is:", optionA: "NDB: aircraft position; VOR: beacon position", optionB: "NDB: beacon position; VOR: aircraft position", optionC: "NDB: aircraft position; VOR: aircraft position", optionD: "NDB: beacon position; VOR: beacon position", correctAnswer: "a", explanation: "ADF bearing uses variation at the aircraft; VOR radial is referenced to variation at the beacon.", difficulty: "hard" },
  { id: "IRRN-083", sectionId: "C.2.2", question: "The BFO selector switch on the ADF control panel must be in the 'on' position to enable the pilot to:", optionA: "adjust the loop to the aural null position", optionB: "stop the loop rotation", optionC: "hear the IDENT of NDBs using NON A1A transmissions", optionD: "hear the IDENT of NDBs using NON A2A transmissions", correctAnswer: "c", explanation: "The BFO makes the unmodulated NON/A1A carrier audible for identification.", difficulty: "medium" },
  { id: "IRRN-084", sectionId: "C.2.2", question: "When receiving an NDB signal on an ADF receiver the BFO can be selected OFF for the:", optionA: "tone signal on NONA2A", optionB: "tone signal on NONA1A", optionC: "ident signal on NONA1A", optionD: "ident signal on NONA2A", correctAnswer: "d", explanation: "A NON/A2A NDB is already modulated with an audible tone, so the BFO can be OFF to hear its ident.", difficulty: "medium" },
  { id: "IRRN-085", sectionId: "C.2.2", question: "There are two modulation types of NDBs: NON/A1A and NON/A2A. Which of the following statements is true?", optionA: "The bearing indicator is erratic when an NON/A1A station is identifying", optionB: "The bearing indicator is erratic when an NON/A2A station is identifying", optionC: "In order to identify an NON/A2A station the BFO has to be activated", optionD: "The transmitted identification modulation frequency of an NON/A1A station is 1020 Hz", correctAnswer: "a", explanation: "Keying a NON/A1A carrier for ident interrupts it, so the ADF needle becomes erratic during identification.", difficulty: "hard" },
  { id: "IRRN-086", sectionId: "C.2.2", question: "On modern aircraft, the BFO:", optionA: "needs to be switched off with an N0N/A1A transmission", optionB: "must be switched on with an N0N/A2A transmission", optionC: "is automatically activated, when necessary", optionD: "should be activated when receiving a Locator transmission", correctAnswer: "c", explanation: "Modern ADF receivers activate the BFO automatically when a NON/A1A signal requires it.", difficulty: "medium" },
  { id: "IRRN-087", sectionId: "C.2.2", question: "An NDB is on a relative bearing of 316° from an aircraft. Given: Compass heading 270°, aircraft deviation 2°W, Variation 30°E at the aircraft and 28°E at the station. Calculate the true bearing of the NDB from the aircraft:", optionA: "254°", optionB: "074°", optionC: "270°", optionD: "046°", correctAnswer: "a", explanation: "True HDG = 270 − 2 (dev) + 30 (var E) = 298; QDR true = 298 + 316 = 614 − 360 = 254°.", difficulty: "hard" },
  { id: "IRRN-088", sectionId: "C.2.5", question: "Concerning the localiser principle of operation in an ILS, the needle of the aircraft indicator is centred when the difference in depth of modulation (DDM) is:", optionA: "less than 90 Hz", optionB: "more than 150 Hz", optionC: "null", optionD: "maximum", correctAnswer: "c", explanation: "On the localiser centre line the 90 Hz and 150 Hz depths are equal, so DDM is zero (null) and the needle is centred.", difficulty: "medium" },
  { id: "IRRN-089", sectionId: "C.2.2", question: "In a modern FMS equipped aircraft with a modern ADF receiver, the Beat Frequency Oscillator (BFO):", optionA: "Must be activated by hand", optionB: "Is activated automatically", optionC: "Is not installed because NON/A1A NDB stations are no longer in use in modern aviation", optionD: "May be activated either automatically or by hand", correctAnswer: "b", explanation: "In a modern FMS/ADF the BFO is activated automatically when required.", difficulty: "medium" },
  { id: "IRRN-090", sectionId: "C.2.2", question: "Which of the following factors could cause an error of an ADF bearing of an NDB?", optionA: "Night effect", optionB: "Phase interference", optionC: "Atmospheric scatter", optionD: "Scalloping", correctAnswer: "a", explanation: "Night effect (sky-wave interference) is a classic cause of ADF bearing error.", difficulty: "medium" },
  { id: "IRRN-091", sectionId: "C.2.2", question: "NDB is the abbreviation for:", optionA: "Non Directional Beacon", optionB: "Navigation Director Beacon", optionC: "Non Directional Bearing", optionD: "Night Directional Beacon", correctAnswer: "a", explanation: "NDB = Non Directional Beacon.", difficulty: "easy" },
  { id: "IRRN-092", sectionId: "C.2.2", question: "According to ICAO Annex 10, in which frequency band(s) does a locator normally transmit?", optionA: "HF", optionB: "MF/HF", optionC: "LF/MF", optionD: "HF/VHF", correctAnswer: "c", explanation: "Locators are low-power NDBs transmitting in the LF/MF band.", difficulty: "medium" },
  { id: "IRRN-093", sectionId: "C.2.2", question: "A locator beacon differs from an NDB with respect to: (1) operational use (2) transmission power (3) presentation in the cockpit (4) frequency band. From the above stated differences, the following numbers are correct:", optionA: "1 and 4", optionB: "2, 3 and 4", optionC: "1 and 2", optionD: "None of the above", correctAnswer: "c", explanation: "A locator differs only in its operational use (final approach) and its lower transmission power; presentation and frequency band are the same as any NDB.", difficulty: "medium" },
  { id: "IRRN-094", sectionId: "C.2.2", question: "On the QDR of 075° (in the vicinity of the station) with a magnetic heading of 295°, the relative bearing on the ADF indicator is:", optionA: "140°", optionB: "220°", optionC: "320°", optionD: "040°", correctAnswer: "c", explanation: "QDM = QDR ± 180 = 255°; relative bearing = QDM − heading = 255 − 295 = −40 = 320°.", difficulty: "hard" },
  { id: "IRRN-095", sectionId: "C.2.2", question: "Which statement about the errors and effects on NDB radio signals is correct?", optionA: "The mountain effect is caused by reflections onto steep slopes of mountainous terrain which may cause big errors in the bearing", optionB: "Night effect is a result of interference of the surface wave and the space wave causing a reduction in range", optionC: "Lightning during atmospheric disturbances may cause a reduction of the signal strength that may result in only slight bearing errors", optionD: "Shore line effects may cause a huge bearing error due to reflection of the radio signal onto steep coasts", correctAnswer: "a", explanation: "Mountain effect is caused by signal reflection off steep terrain, giving large bearing errors.", difficulty: "medium" },
  { id: "IRRN-096", sectionId: "C.2.2", question: "Which statement about ADFs is correct?", optionA: "ADFs can receive and take bearings on any broadcasting station transmitting within the frequency band/range 190 - 1750 kHz", optionB: "ADFs can't receive broadcasting stations transmitting within 190 - 1750 kHz because NDBs are typically N0N/A1A or A2A modulated and not A3E modulated like broadcasting stations", optionC: "ADFs can't receive broadcasting stations within 190 - 1750 kHz because NDBs are amplitude modulated and not frequency modulated like VHF broadcasting stations", optionD: "ADFs can receive any broadcasting station transmitting within 190 - 1750 kHz but cannot take bearings on them", correctAnswer: "a", explanation: "An ADF can receive and take a bearing on any station transmitting in its 190–1750 kHz band, including broadcast stations.", difficulty: "medium" },
  { id: "IRRN-097", sectionId: "C.2.3", question: "The principle used in VOR bearing measurement is:", optionA: "phase comparison", optionB: "envelope matching", optionC: "beat frequency discrimination", optionD: "difference in depth of modulation", correctAnswer: "a", explanation: "VOR measures the phase difference between the reference and variable signals.", difficulty: "medium" },
  { id: "IRRN-098", sectionId: "C.2.3", question: "The three main components of VOR airborne equipment are:", optionA: "Display, Pulse generator, phase comparator", optionB: "Receiver, Antenna, Display", optionC: "Receiver, Phase comparator, Range gate", optionD: "Demodulator, Antenna, CDU", correctAnswer: "b", explanation: "The VOR airborne installation comprises the receiver, the antenna and the display.", difficulty: "medium" },
  { id: "IRRN-099", sectionId: "C.2.3", question: "A pilot flying an aircraft at FL 80 tunes in a VOR which has an elevation of 313 m. Given ISA conditions, what is the maximum theoretical distance at which a pilot might expect to receive the VOR signals?", optionA: "180 NM", optionB: "100 NM", optionC: "120 NM", optionD: "149 NM", correctAnswer: "d", explanation: "Line-of-sight VHF range ≈ 1.23(√8000 + √1027 ft) ≈ 149 NM.", difficulty: "medium" },
  { id: "IRRN-100", sectionId: "C.2.3", question: "A multifunctional display shows VOR 1 tuned to a nearby VOR (CRS 130 selected). With the deviation displayed, the aircraft is:", optionA: "3° right of the selected radial 310, outbound", optionB: "3° left of the selected radial 130, inbound", optionC: "6° right of the selected radial 310, outbound", optionD: "6° left of the selected radial 130, inbound", correctAnswer: "d", explanation: "With CRS 130 set (inbound) and full-ish left deviation, the aircraft is 6° left of the 130 radial, tracking inbound.", difficulty: "hard" },
  { id: "IRRN-101", sectionId: "C.2.3", question: "A multifunctional display shows VOR 1 tuned to a nearby VOR (CRS 045 selected). With the deviation displayed, the aircraft is:", optionA: "2.5° right of the selected radial 225 inbound", optionB: "5° right of the selected radial 225 inbound", optionC: "2.5° left of the selected radial 045 outbound", optionD: "5° left of the selected radial 045 outbound", correctAnswer: "d", explanation: "With CRS 045 set (outbound) and full-ish left deviation, the aircraft is 5° left of the 045 radial, tracking outbound.", difficulty: "hard" },
  { id: "IRRN-102", sectionId: "C.2.4", question: "Military UHF tactical air navigation aid (TACAN) stations may...", optionA: "NOT be used by civil aircraft.", optionB: "be used for bearing and range information by civil aircraft.", optionC: "be used for range information by civil aircraft.", optionD: "be used for bearing information by civil aircraft.", correctAnswer: "c", explanation: "Civil aircraft can use the DME (range) element of a TACAN but not its military bearing function.", difficulty: "medium" },
  { id: "IRRN-103", sectionId: "C.2.3", question: "The indication of the FROM/TO indicator of a VOR shifts from TO to FROM (or vice versa) when the value of the difference between the selected course and the measured radial passes, in either direction:", optionA: "045°", optionB: "090°", optionC: "180°", optionD: "135°", correctAnswer: "b", explanation: "The TO/FROM flag reverses as the aircraft crosses the line 90° to the selected course (the abeam/ambiguity line).", difficulty: "medium" },
  { id: "IRRN-104", sectionId: "C.2.3", question: "Which one of the following frequencies can be used by a terminal VOR?", optionA: "111.975 MHz", optionB: "108.20 MHz", optionC: "108.10 MHz", optionD: "118.15 MHz", correctAnswer: "b", explanation: "Terminal VORs use the 108.0–111.975 MHz even-tenth channels shared with ILS localisers; 108.20 MHz is an even-tenth VOR channel.", difficulty: "hard" },
  { id: "IRRN-105", sectionId: "C.2.3", question: "On an RMI the front end of a VOR pointer indicates the:", optionA: "Magnetic bearing to the station", optionB: "Magnetic bearing from the station", optionC: "Radial", optionD: "Radial plus 180°", correctAnswer: "d", explanation: "The RMI VOR needle head shows QDM (magnetic bearing to the station), which equals the radial ±180°.", difficulty: "medium" },
  { id: "IRRN-106", sectionId: "C.2.3", question: "An aircraft is flying on the true track 090° towards a VOR station located near the equator where the magnetic variation is 15°E. The variation at the aircraft position is 8°E. The aircraft is on VOR radial:", optionA: "262°", optionB: "285°", optionC: "278°", optionD: "255°", correctAnswer: "d", explanation: "Radial is referenced to variation at the station: magnetic track to station = 090 − 15 = 075; radial (from station) = 075 + 180 = 255°.", difficulty: "hard" },
  { id: "IRRN-107", sectionId: "C.2.3", question: "In ISA conditions, approximately what is the maximum theoretical range at which an aircraft at FL210 may expect to receive signals from a VOR facility sited 340 feet above mean sea level?", optionA: "163 NM", optionB: "183 NM", optionC: "245 NM", optionD: "204 NM", correctAnswer: "d", explanation: "Line-of-sight range ≈ 1.23(√21000 + √340) ≈ 204 NM.", difficulty: "medium" },
  { id: "IRRN-108", sectionId: "C.2.3", question: "A VOR and an NDB are located in the same position. Both the VOR and the ADF readings are displayed on the RMI. The aircraft is tracking away from the beacons along the 090 radial. The magnetic variation is changing rapidly. Which of the following is correct?", optionA: "The direction of the ADF pointer will change, the direction of the VOR pointer will not change", optionB: "Both the direction of the ADF pointer and the direction of the VOR pointer will change", optionC: "The direction of the VOR pointer will change, the direction of the ADF pointer will not change", optionD: "Neither the direction of the ADF pointer nor the direction of the VOR pointer will change", correctAnswer: "a", explanation: "The VOR radial is fixed relative to the station's variation, so its RMI pointer is unaffected; the ADF uses variation at the aircraft, so its pointer changes as variation changes.", difficulty: "hard" },
  { id: "IRRN-109", sectionId: "C.2.3", question: "TVOR is a:", optionA: "test VOR transmitting such a signal that the reference- and variable signal are always in phase", optionB: "VOR with a limited range used in the terminal area", optionC: "high power VOR in the frequency range 108 MHz - 112 MHz", optionD: "low power DVOR in the frequency range 112 MHz - 118 MHz", correctAnswer: "b", explanation: "A TVOR (terminal VOR) is a low-power VOR with limited range serving a terminal area.", difficulty: "medium" },
  { id: "IRRN-110", sectionId: "C.2.3", question: "Transmissions from VOR facilities may be adversely affected by:", optionA: "quadrantal error", optionB: "night effect", optionC: "uneven propagation over irregular ground surfaces", optionD: "static interference", correctAnswer: "c", explanation: "VOR bearings can be corrupted by site/terrain effects — uneven propagation over irregular ground (scalloping/bending).", difficulty: "medium" },
  { id: "IRRN-111", sectionId: "C.2.3", question: "An aircraft is required to approach a VOR station via the 244° radial. In order to obtain correct sense indications, the deviation indicator should be set to:", optionA: "244° with the TO flag showing", optionB: "064° with the FROM flag showing", optionC: "244° with the FROM flag showing", optionD: "064° with the TO flag showing", correctAnswer: "d", explanation: "To approach inbound along the 244 radial you fly the reciprocal 064° with a TO indication.", difficulty: "medium" },
  { id: "IRRN-112", sectionId: "C.2.3", question: "Which value of variation should be applied to convert true to magnetic bearings at an NDB and VOR?", optionA: "NDB: Variation at the beacon position. VOR: Variation at the beacon position", optionB: "NDB: Variation at the aircraft position. VOR: Variation at the beacon position", optionC: "NDB: Variation at the beacon position. VOR: Variation at the aircraft position", optionD: "NDB: Variation at the mid-latitude. VOR: Variation at the beacon position", correctAnswer: "b", explanation: "ADF/NDB uses variation at the aircraft; VOR radial is referenced to variation at the beacon.", difficulty: "hard" },
  { id: "IRRN-113", sectionId: "C.2.3", question: "Which of the following errors is associated with the use of VOR?", optionA: "Night effect", optionB: "Quadrantal error", optionC: "Coastal refraction", optionD: "Scalloping", correctAnswer: "d", explanation: "Scalloping (momentary bearing fluctuation from terrain reflections) is a VOR error.", difficulty: "medium" },
  { id: "IRRN-114", sectionId: "C.2.3", question: "The principle advantage of Doppler VOR is that:", optionA: "transmitter frequency instability is minimised", optionB: "site errors are considerably reduced", optionC: "a readout of range as well as bearing is obtained", optionD: "the effective range is increased", correctAnswer: "b", explanation: "The Doppler VOR's wide antenna aperture greatly reduces site/terrain (scalloping) errors.", difficulty: "medium" },
  { id: "IRRN-115", sectionId: "C.2.3", question: "When using an RMI as an indicator for the VOR receiver:", optionA: "The TO/FROM indication on the RMI will indicate which way to turn the aircraft in order to fly towards the VOR station being received", optionB: "You will read the number of the received radial under the tip of the VOR needle", optionC: "You will read the number of the received radial under the tail of the VOR needle", optionD: "You will read the drift as the angle between the OBS bug and the tip of the VOR needle", correctAnswer: "c", explanation: "On an RMI the needle head shows QDM (bearing to); the radial (QDR) is read under the tail.", difficulty: "medium" },
  { id: "IRRN-116", sectionId: "C.2.3", question: "A VOR indication of 240° FROM is given. Variation at the aircraft is 9°W and at the VOR is 7°W. The heading °(T) in nil wind to reach the station is:", optionA: "233°", optionB: "231°", optionC: "051°", optionD: "053°", correctAnswer: "d", explanation: "QDM(mag) = 240 − 180 = 060; true track = 060 − 7 (VOR var W) = 053°.", difficulty: "hard" },
  { id: "IRRN-117", sectionId: "C.2.3", question: "An aircraft is on radial 120 with a magnetic heading of 300°, the track selector (OBS) reads 330. The indications on the Course Deviation Indicator (CDI) are 'fly':", optionA: "left with 'FROM' showing", optionB: "right with 'TO' showing", optionC: "left with 'TO' showing", optionD: "right with 'FROM' showing", correctAnswer: "c", explanation: "OBS 330 with a TO sense (reciprocal of radial 120 = 300 inbound) and the aircraft 30° clockwise of course gives a fly-left, TO indication.", difficulty: "hard" },
  { id: "IRRN-118", sectionId: "C.2.3", question: "Which of the following is a valid frequency (MHz) for a VOR:", optionA: "118.35", optionB: "112.20", optionC: "109.90", optionD: "107.75", correctAnswer: "b", explanation: "VOR frequencies lie 108.0–117.975 MHz; 112.20 MHz is a valid VOR channel.", difficulty: "medium" },
  { id: "IRRN-119", sectionId: "C.2.3", question: "Given: VOR station position N61° E025°, variation 13°E. Estimated position of an aircraft N59° E025°, variation 20°E. What VOR radial is the aircraft on?", optionA: "167°", optionB: "193°", optionC: "347°", optionD: "160°", correctAnswer: "a", explanation: "Aircraft is due south of the station: true bearing from station = 180; radial (magnetic at station) = 180 − 13 = 167°.", difficulty: "hard" },
  { id: "IRRN-120", sectionId: "C.2.3", question: "The basic principle of operation of the VOR is by:", optionA: "pulse difference between a 30 Hz reference signal and a 30 Hz variable signal", optionB: "phase comparison between a 63 Hz reference signal and a 63 Hz variable signal", optionC: "phase comparison between a 30 Hz reference signal and a 63 Hz variable signal", optionD: "phase comparison between a 30 Hz reference signal and a 30 Hz variable signal", correctAnswer: "d", explanation: "VOR compares the phase of a 30 Hz reference signal with a 30 Hz variable signal.", difficulty: "medium" },
  { id: "IRRN-121", sectionId: "C.2.3", question: "The frequency range of a VOR receiver is:", optionA: "108 to 117.95 MHz", optionB: "118 to 135.95 MHz", optionC: "108 to 135.95 MHz", optionD: "108 to 111.95 MHz", correctAnswer: "a", explanation: "VOR receivers cover 108–117.975 MHz.", difficulty: "medium" },
  { id: "IRRN-122", sectionId: "C.2.3", question: "A VOR is sited at position A (45°00'N, 010°00'E). An aircraft is located at position B (44°00'N, 010°00'E). Assuming that the magnetic variation at A is 10°W and at B is 15°W, the aircraft is on VOR radial:", optionA: "180°", optionB: "195°", optionC: "185°", optionD: "190°", correctAnswer: "d", explanation: "Aircraft is due south of the station: true bearing from = 180; radial (magnetic at station) = 180 + 10 (var W) = 190°.", difficulty: "hard" },
  { id: "IRRN-123", sectionId: "C.2.3", question: "If the compass providing information to the RMI suddenly gets a 20° deviation:", optionA: "The number of the received radial may still be read on the compass card under the tail of the VOR needle", optionB: "The relative bearing to the VOR, as observed on the RMI, will jump 20°", optionC: "The magnetic track to the VOR station may be read on the compass card under the tip of the VOR needle", optionD: "All 3 answers are correct", correctAnswer: "d", explanation: "The RMI VOR needle points at the compass card, so a compass error shifts all indications equally — each of the three statements remains individually true relative to the card.", difficulty: "hard" },
  { id: "IRRN-124", sectionId: "C.2.4", question: "Which one of the statements below regarding DME is correct?", optionA: "The DME ground station is always co-located with a VOR station", optionB: "Two lines of position obtained from two different DMEs give an unambiguous fix", optionC: "The DME operating frequencies are in the UHF band", optionD: "The indicated distance is the ground distance measured from the aircraft's projected position on the ground to the DME ground installation", correctAnswer: "c", explanation: "DME operates in the UHF band (960–1215 MHz).", difficulty: "medium" },
  { id: "IRRN-125", sectionId: "C.2.4", question: "If the number of pulse pairs received by the DME transponder exceeds the maximum number possible, which aircraft will always be denied a DME range first?", optionA: "The smallest aircraft which is using the DME station for range measurement", optionB: "The aircraft at the lowest altitude", optionC: "The aircraft at the largest distance from the DME station", optionD: "The aircraft from which the weakest pulse pairs are received", correctAnswer: "d", explanation: "When saturated (typically ~100 aircraft) the DME transponder gives priority to the strongest signals, dropping the weakest first.", difficulty: "medium" },
  { id: "IRRN-126", sectionId: "C.2.4", question: "How can a DME interrogator distinguish between its own reply pulse pairs and the reply pulse pairs of other aircraft in the area, using the same DME-station?", optionA: "The Pulse Repetition Frequency of the pulse-pairs transmitted by the interrogator varies, for each interrogator, in a unique rhythm", optionB: "On the Y-channel the time interval between the pulses of an interrogator pulse pair is 36 m/sec and of a transponder pulse-pair 30 m/sec", optionC: "The DME transponder uses a slightly different, randomly varying, delay for each interrogating aircraft", optionD: "The time interval between both pulses of consecutive pulse pairs transmitted by the interrogator varies, for each interrogator, in a unique pattern", correctAnswer: "a", explanation: "Each interrogator jitters its PRF in a unique random rhythm, so it recognises only the replies that echo its own timing.", difficulty: "hard" },
  { id: "IRRN-127", sectionId: "C.2.4", question: "Of what use, if any, is a military TACAN station to civil aviation?", optionA: "It can provide a magnetic bearing", optionB: "It can provide a DME distance and magnetic bearing", optionC: "It can provide DME distance", optionD: "It is of no use to civil aviation", correctAnswer: "c", explanation: "Civil aircraft can use the DME (range) portion of a TACAN but not its bearing function.", difficulty: "medium" },
  { id: "IRRN-128", sectionId: "C.2.4", question: "The identification of a DME in combination with a collocated VOR is as follows:", optionA: "The VOR ident and DME ident are the same and no difference can be heard", optionB: "Every 30 seconds the DME ident will be repeated", optionC: "In a period of 40 seconds the DME ident will be heard once on an audio frequency of 1350 Hz", optionD: "The DME ident will repeat three times every period of 30 seconds", correctAnswer: "c", explanation: "A collocated DME idents once about every 40 seconds at 1350 Hz (the VOR idents more often at 1020 Hz).", difficulty: "medium" },
  { id: "IRRN-129", sectionId: "C.2.4", question: "Flying over Russia a DME slant range reads 1.5 NM. The aircraft is on the approach flying 1,000 m above the DME elevation. The distance from the aircraft ground position to the DME station is:", optionA: "2,591 m", optionB: "780 m", optionC: "1,500 m", optionD: "1,119 m", correctAnswer: "a", explanation: "Ground distance = √(slant² − height²) = √(2778² − 1000²) ≈ 2,591 m (1.5 NM = 2778 m).", difficulty: "hard" },
  { id: "IRRN-130", sectionId: "C.2.4", question: "An aircraft is equipped with a DME receiver that provides a ground speed read-out. It is flying a DME arc and is descending in an approach procedure. The ground speed calculated by the DME computer is:", optionA: "Higher than the actual ground speed as the ground distance increases", optionB: "Accurately measured and indicated", optionC: "Zero knots as the slant range remains constant", optionD: "Lower than the actual ground speed when the height decreases", correctAnswer: "c", explanation: "On a DME arc the slant range stays constant, so the DME-derived ground speed reads zero regardless of actual speed.", difficulty: "medium" },
  { id: "IRRN-131", sectionId: "C.2.4", question: "What is the reason that a DME-station can generally respond to a maximum of 100 aircraft?", optionA: "The minimum allowable accuracy of the range-measurement cannot be guaranteed when more than 100 aircraft are using the same DME station", optionB: "The memory of the DME-transponder is limited", optionC: "The automatic ground monitoring station of each DME-station has a limited capacity", optionD: "The number of reply pulse pairs per second, that a DME-transponder can transmit, is limited to a certain maximum value", correctAnswer: "d", explanation: "The transponder's reply-pulse-pair rate is capped, which limits it to roughly 100 aircraft.", difficulty: "medium" },
  { id: "IRRN-132", sectionId: "C.2.4", question: "What navigation procedure involves a constant Distance Measuring Equipment (DME) range and a groundspeed of zero?", optionA: "DME Arc", optionB: "Holding Pattern", optionC: "VOR Approach", optionD: "GPS Waypoint", correctAnswer: "a", explanation: "Flying a DME arc keeps slant range constant, so DME-derived ground speed reads zero.", difficulty: "medium" },
  { id: "IRRN-133", sectionId: "C.2.4", question: "An aircraft DME receiver does not lock on to its own transmissions reflected from the ground because:", optionA: "the pulse recurrence rates are varied", optionB: "DME transmits twin pulses", optionC: "they are not on the receiver frequency", optionD: "DME uses the UHF band", correctAnswer: "c", explanation: "The transponder replies on a frequency 63 MHz offset from the interrogation, so ground reflections of the interrogation are not on the receive frequency.", difficulty: "medium" },
  { id: "IRRN-134", sectionId: "C.2.4", question: "When flying at 6000 feet above ground level, the DME indicates 5 NM. What is the horizontal distance from the aircraft to the overhead DME?", optionA: "4.6 NM", optionB: "5.2 NM", optionC: "4.9 NM", optionD: "4.3 NM", correctAnswer: "c", explanation: "6000 ft ≈ 0.99 NM; ground distance = √(5² − 0.99²) ≈ 4.9 NM.", difficulty: "medium" },
  { id: "IRRN-135", sectionId: "C.2.4", question: "The ident of a DME in case of collocation with a VOR is as follows:", optionA: "In 40 seconds the DME ident will sound once", optionB: "The DME ident comes up every 10 seconds at an audio frequency of 1020 Hz", optionC: "In 30 seconds the DME ident comes up 3 times at an audio frequency of 1350 Hz", optionD: "In case of collocation the DME ident is not necessary if the VOR ident is present", correctAnswer: "a", explanation: "A collocated DME transmits its ident about once every 40 seconds.", difficulty: "medium" },
  { id: "IRRN-136", sectionId: "C.2.7", question: "If the Single European Sky legislation is not applicable, the SSR transponders should operate in accordance with the relevant provisions of Volume IV of ICAO Annex:", optionA: "18", optionB: "6", optionC: "10", optionD: "17", correctAnswer: "c", explanation: "SSR transponder requirements are in ICAO Annex 10 (Aeronautical Telecommunications), Volume IV.", difficulty: "medium" },
  { id: "IRRN-137", sectionId: "C.2.7", question: "When an aircraft is operating its Secondary Surveillance Radar in Mode C, an air traffic controller's presentation gives information regarding the aircraft's indicated pressure altitude in increments of:", optionA: "100 m", optionB: "25 ft", optionC: "100 ft", optionD: "50 m", correctAnswer: "c", explanation: "Mode C reports pressure altitude in 100 ft increments.", difficulty: "medium" },
  { id: "IRRN-138", sectionId: "C.2.7", question: "When and from which station is an SPI (Special Position Identification) pulse sent?", optionA: "From the aircraft transponder, when the pilot pushes the IDENT button", optionB: "From the SSR ground station, in order to request the identification of an aircraft", optionC: "From the SSR ground station, and it is sent with all transmissions to identify the station", optionD: "From the aircraft transponder, when the pilot selects a new squawk code", correctAnswer: "a", explanation: "The SPI pulse is transmitted by the aircraft transponder when the pilot presses IDENT.", difficulty: "medium" },
  { id: "IRRN-139", sectionId: "C.2.6", question: "Airborne weather radar systems (AWR) should be used with extreme caution when on the ground. The reason is:", optionA: "People could be exposed to SHF (super high frequency) radiation which can lead to damage of the tissues when absorbed in larger amounts", optionB: "The radar system may overheat and shut down because it receives high intensity returns from the ground, from buildings and from surrounding terrain", optionC: "The intense returns from the ground and surrounding terrain will not allow accurate identification of potentially hazardous weather when lined up for departure", optionD: "The radar antenna can be easily damaged during ground taxi manoeuvres (especially on uneven taxiways)", correctAnswer: "a", explanation: "AWR transmits SHF energy that can harm human tissue, so it must not be transmitted while people are near the aircraft on the ground.", difficulty: "medium" },
  { id: "IRRN-140", sectionId: "C.2.7", question: "What will a mode S transponder reply to?", optionA: "SSR and ADS-B interrogations", optionB: "SSR and primary radar interrogations", optionC: "SSR and TCAS interrogations", optionD: "TCAS and ADS-B interrogations", correctAnswer: "c", explanation: "A Mode S transponder replies to SSR ground interrogations and to airborne TCAS interrogations.", difficulty: "medium" },
  { id: "IRRN-141", sectionId: "C.2.7", question: "How can an SSR interrogation be directed toward a specific aircraft?", optionA: "by limiting the beam width of the SSR transmission", optionB: "controller Pilot Data Link Communications (CPDLC) will reply with a unique aircraft identifier", optionC: "with a unique 24 bit address in the interrogation", optionD: "the SSR interrogation is directed to the aircraft's position", correctAnswer: "c", explanation: "Mode S selective interrogation addresses one aircraft by its unique 24-bit address.", difficulty: "medium" },
  { id: "IRRN-142", sectionId: "C.2.7", question: "The allocation of 24-bit aircraft addresses is described in ICAO annex 10, it states that:", optionA: "civil aircraft will have been allocated with an ICAO Aircraft Address which is hard coded into the airframe", optionB: "every aircraft will have been allocated with an ICAO Aircraft Address which is hard coded into the airframe", optionC: "military aircraft will have been allocated with an ICAO Aircraft Addresses which is hard coded into the airframe", optionD: "every aircraft will have been allocated with a NATO Aircraft Address which is hard coded into the airframe", correctAnswer: "b", explanation: "Every aircraft is allocated a unique ICAO 24-bit aircraft address, hard-coded into the airframe.", difficulty: "medium" },
  { id: "IRRN-143", sectionId: "C.2.4", question: "After a DME arc entry at the fix, the aircraft shall enter the holding pattern in accordance with the:", optionA: "Sector 1 or Sector 2 procedure", optionB: "Sector 1,2 or 3 procedure", optionC: "Sector 1 or Sector 3 procedure", optionD: "Sector 2 or Sector 3 procedure", correctAnswer: "c", explanation: "Following a DME arc entry to the fix, the hold is entered using a Sector 1 or Sector 3 (offset/parallel) entry.", difficulty: "hard" },
  { id: "IRRN-144", sectionId: "C.2.7", question: "From the list below, select the appropriate types of data that may be shown on an ATC display system. (1) Flight number (call sign) (2) Pressure altitude (3) Radio altitude (4) Autopilot modes (5) Ground speed.", optionA: "3,4 and 5 only", optionB: "1,2,3 and 5", optionC: "1,2,3 and 4", optionD: "1,2 and 5 only", correctAnswer: "d", explanation: "SSR Mode S downlinks call sign, pressure altitude and ground speed to the ATC display; radio altitude and autopilot modes are not shown.", difficulty: "medium" },
  { id: "IRRN-145", sectionId: "C.2.7", question: "A Mode S transponder with enhanced vertical tracking can provide altitude reporting in increments of:", optionA: "125 feet", optionB: "100 feet", optionC: "25 feet", optionD: "50 feet", correctAnswer: "c", explanation: "Mode S enhanced surveillance reports altitude in 25 ft increments (versus 100 ft for Mode C).", difficulty: "medium" },
  { id: "IRRN-146", sectionId: "C.2.7", question: "The advantages of Secondary Surveillance Radar (SSR) compared to Primary Radar are that SSR (1)________ and has a longer range because (2)________:", optionA: "(1) provides coded replies; (2) of its higher transmission power", optionB: "(1) enables the controller to have an organized display; (2) it uses long interrogation pulses", optionC: "(1) collects more data; (2) of the active participation of the aircraft's transponder", optionD: "(1) uses smaller aerials; (2) it operates at higher frequencies", correctAnswer: "c", explanation: "SSR collects more data (identity, altitude) and reaches further because the transponder actively replies rather than relying on a passive echo.", difficulty: "medium" },
  { id: "IRRN-147", sectionId: "C.2.7", question: "Which one of the following switch positions should be used when selecting a code on the Transponder?", optionA: "NORMAL", optionB: "OFF", optionC: "IDENT (Identification)", optionD: "STBY (Standby)", correctAnswer: "d", explanation: "Select a new squawk with the transponder in STBY to avoid transmitting a transient/incorrect code.", difficulty: "medium" },
  { id: "IRRN-148", sectionId: "C.2.7", question: "The Secondary Surveillance Radar (SSR) Mode S transponder will transmit a 24-bit Aircraft Address (AA). The Aircraft Address is:", optionA: "an ICAO code corresponding to the aircraft identification number, which is set from the flight deck", optionB: "a unique code associated with the Operator and the flight number", optionC: "the squawk code as assigned by ATC", optionD: "a unique identification number that is hard-coded into the transponder", correctAnswer: "d", explanation: "The 24-bit aircraft address is a unique identity hard-coded into the airframe/transponder.", difficulty: "medium" },
  { id: "IRRN-149", sectionId: "C.2.7", question: "The Secondary Surveillance Radar (SSR) mode S is compatible with (1) but also provides the information for (2):", optionA: "(1) Airborne Weather Radar (AWR); (2) the Traffic alert and Collision Avoidance System (TCAS)", optionB: "(1) Distance Measuring Equipment; (2) enhanced vertical tracking", optionC: "(1) the radio altimeter; (2) SSR mode C", optionD: "(1) SSR mode A and C; (2) Automatic Dependent Surveillance - Broadcast (ADS-B)", correctAnswer: "d", explanation: "Mode S is backward compatible with Modes A and C and provides the data for ADS-B.", difficulty: "medium" },
  { id: "IRRN-150", sectionId: "C.2.6", question: "The gain control knob of an AWR adjusts:", optionA: "The receiver sensitivity in order to achieve optimum target acquisition", optionB: "The brightness of the display", optionC: "The automatic gain control of the AWR is activated", optionD: "The power level of the transmitted energy is made dependent on the selected", correctAnswer: "a", explanation: "The gain control sets receiver sensitivity for optimum target/return acquisition.", difficulty: "medium" },
  { id: "IRRN-151", sectionId: "C.2.7", question: "What is an advantage of an SSR with a 'selective addressing mode' over primary radar?", optionA: "It allows for unambiguous aircraft identification", optionB: "In case of a transponder malfunction, the SSR can be used as a primary radar", optionC: "Its range is unrelated to its transmitting power", optionD: "It is independent from airborne-and space-based systems", correctAnswer: "a", explanation: "Mode S selective addressing gives each aircraft a unique address, allowing unambiguous identification.", difficulty: "medium" },
  { id: "IRRN-152", sectionId: "C.2.6", question: "The airborne weather radar:", optionA: "Has a second transmitter working on a lower frequency in order to penetrate rain showers", optionB: "may receive no reflections from a thunderstorm in an areas behind a heavy rain shower", optionC: "Has the possibility to detect clear air turbulence behind a thunderstorm by measuring phase-differences caused by the Doppler effect", optionD: "Uses circular polarisation in order to reduce echoes of heavy shower", correctAnswer: "b", explanation: "A near cell of heavy rain attenuates the beam (shadowing), so a storm behind it may produce no return.", difficulty: "medium" },
  { id: "IRRN-153", sectionId: "C.2.7", question: "Which statement is correct with respect to selections on the transponder control panel?", optionA: "With ALT selected a reply in the modes A, C and S can be transmitted", optionB: "With ON selected a reply in the modes A, C and S can be transmitted", optionC: "With the selector knobs the four digits of the squawk can be selected using the decimal symbols 0 through 9", optionD: "The current ICAO 24 bits aircraft address code must be inserted on the control panel", correctAnswer: "a", explanation: "With ALT (Mode C) selected the transponder replies in Modes A, C and S; squawk digits are octal (0–7).", difficulty: "medium" },
  { id: "IRRN-154", sectionId: "C.2.7", question: "When Mode C is selected on the aircraft SSR transponder, the additional information transmitted is:", optionA: "altitude based on regional QNH", optionB: "height based on QFE", optionC: "aircraft height based on sub-scale setting", optionD: "flight level based on 1013.25 hPa", correctAnswer: "d", explanation: "Mode C transmits pressure altitude referenced to 1013.25 hPa (flight level).", difficulty: "medium" },
  { id: "IRRN-155", sectionId: "C.2.6", question: "Find the correct statement concerning an airborne weather radar.", optionA: "An airborne weather radar uses several transmitters with varying frequencies to give information about areas behind heavy precipitation", optionB: "An airborne weather radar may show ground reflections, even when turned off", optionC: "An airborne weather radar may show no reflections of a thunderstorm cell which is situated behind an area with heavy precipitation", optionD: "An airborne weather radar uses circular polarisation to reduce ground clutter and echoes of heavy precipitation", correctAnswer: "c", explanation: "Attenuation (shadowing) by nearer heavy precipitation can hide a storm cell behind it.", difficulty: "medium" },
  { id: "IRRN-156", sectionId: "C.2.6", question: "Which of the following is a complete list of airborne weather radar antenna stabilization modes?", optionA: "Pitch and yaw", optionB: "Roll, pitch and yaw", optionC: "Roll and pitch", optionD: "Roll and yaw", correctAnswer: "c", explanation: "The AWR antenna is stabilised about the roll and pitch axes (not yaw).", difficulty: "medium" },
  { id: "IRRN-157", sectionId: "C.2.6", question: "When using the AWR to detect long range ground features the most suitable mode of operation or beam selected would be:", optionA: "the mapping mode", optionB: "the manual mode", optionC: "the contour mode", optionD: "the fan shaped beam", correctAnswer: "b", explanation: "Manual gain/tilt control gives the best long-range ground-feature mapping.", difficulty: "medium" },
  { id: "IRRN-158", sectionId: "C.2.6", question: "In an Airborne Weather Radar the areas of greatest turbulence are usually indicated on the screen by:", optionA: "blank areas where there is no colour", optionB: "colour zones of green and yellow", optionC: "colour zones of red and magenta", optionD: "areas which are coloured black", correctAnswer: "c", explanation: "The heaviest precipitation/turbulence shows as red and magenta on the AWR display.", difficulty: "medium" },
  { id: "IRRN-159", sectionId: "C.2.6", question: "To improve the detection of precipitation area(s) in a thunderstorm, in which the top of the cloud lies at or near slightly above the level of flight:", optionA: "The tilt setting should be higher when the aircraft climbs to a higher altitude", optionB: "The tilt setting should be higher when the selected range decreases", optionC: "The tilt setting should be lower when the selected range increases", optionD: "The tilt setting should be lower when the aircraft climbs to a higher altitude", correctAnswer: "d", explanation: "As the aircraft climbs, the tilt must be lowered to keep the beam on the cloud top ahead.", difficulty: "hard" },
  { id: "IRRN-160", sectionId: "C.2.6", question: "In order to ascertain whether a cloud return on an Aircraft Weather Radar (AWR) is at or above the height of the aircraft, the tilt control should be set to: (Assume a beam width of 5°)", optionA: "5° up", optionB: "0°", optionC: "2.5° down", optionD: "2.5° up", correctAnswer: "d", explanation: "Tilting up by half the beam width (2.5°) puts the lower edge of the beam on the horizon, so a return that persists is at or above the aircraft.", difficulty: "hard" },
  { id: "IRRN-161", sectionId: "C.2.6", question: "A modern Airborne weather Radar (AWR) uses a flat plate antenna with a:", optionA: "Cosecant squared beam with the tilt set downward for ground mapping", optionB: "Pencil or conical beam with the tilt set downward for ground mapping", optionC: "Pencil or conical beam with the tilt set to aircraft pitch for ground mapping", optionD: "Cosecant squared beam with the tilt set to the aircraft pitch for ground mapping as the beam spreads out vertically to the ground", correctAnswer: "b", explanation: "A modern flat-plate AWR radiates a narrow pencil/conical beam, tilted down for ground mapping.", difficulty: "medium" },
  { id: "IRRN-162", sectionId: "C.2.6", question: "The tilt angle of an Airborne Weather Radar (AWR) is set at +2°. If the beam width is 4° and the range of the cloud is 40 NM, what is the approximate height of the cloud above or below the aircraft when the weather return from the cloud just disappears from the screen?", optionA: "6000 above", optionB: "4000 below", optionC: "4000 above", optionD: "6000 below", correctAnswer: "a", explanation: "The return disappears when the beam's lower edge (2° + 2° = 4° up) passes below the cloud: 4° × 40 NM ≈ 4° × 6076 ft/NM ×40/60 ≈ 6000 ft above.", difficulty: "hard" },
  { id: "IRRN-163", sectionId: "C.2.6", question: "Which statement relating to the stabilization of airborne weather radar antennae is true?", optionA: "They are stabilized with respect to the pitch and roll axis but not with respect to the yaw-axis.", optionB: "The pilot can choose the axes of stabilization with the system's stabilization selector switch.", optionC: "They are stabilized with respect to the pitch, roll, and yaw-axis.", optionD: "They are stabilized with respect to the yaw-axis, but not with respect to the pitch and roll axis.", correctAnswer: "a", explanation: "The AWR antenna is stabilised in pitch and roll only (not yaw).", difficulty: "medium" },
  { id: "IRRN-164", sectionId: "C.2.7", question: "Transponder mode C altitude information is transmitted based on:", optionA: "QFF", optionB: "QNE", optionC: "QNH", optionD: "QFE", correctAnswer: "b", explanation: "Mode C altitude is referenced to the standard 1013.25 hPa setting (QNE).", difficulty: "medium" },
  { id: "IRRN-165", sectionId: "C.2.7", question: "When an aircraft is operating its Secondary Surveillance Radar in Mode C, an air traffic controller's presentation gives information regarding the aircraft's indicated flight level in increments of:", optionA: "500", optionB: "100", optionC: "50", optionD: "200", correctAnswer: "b", explanation: "Mode C reports in 100 ft increments (i.e. one flight level step).", difficulty: "medium" },
  { id: "IRRN-166", sectionId: "C.2.7", question: "What is the maximum number of Secondary Surveillance Radar (SSR) transponder codes in Mode A?", optionA: "760", optionB: "1000", optionC: "4096", optionD: "3600", correctAnswer: "c", explanation: "Mode A uses four octal digits: 8⁴ = 4096 possible codes.", difficulty: "medium" },
  { id: "IRRN-167", sectionId: "C.2.7", question: "Which of the following equipment works on the interrogator/transponder principle?", optionA: "Ground Proximity Warning System (GPWS)", optionB: "Secondary Surveillance Radar (SSR)", optionC: "Airborne Weather Radar (AWR)", optionD: "Global Positioning System (GPS)", correctAnswer: "b", explanation: "SSR works on the interrogation/transponder-reply principle (as do DME and TCAS).", difficulty: "medium" },
  { id: "IRRN-168", sectionId: "C.2.7", question: "One of the advantages of the secondary Surveillance Radar (SSR) systems over the primary Surveillance Radar (PSR) systems is that SSR can provide more information. How does this happen?", optionA: "ATC SSR systems can interrogate aircraft transponders and elicit replies", optionB: "ATC SSR systems can reply to an aircraft interrogation and provide requested information", optionC: "ATC SSR systems permanently interrogate aircraft within range, so the tracking is not interrupted", optionD: "ATC SSR systems have moving target indicator capability, which eliminates clutter so more aircraft can be tracked", correctAnswer: "a", explanation: "SSR interrogates the aircraft transponder, which actively replies with identity and altitude data.", difficulty: "medium" },
  { id: "IRRN-169", sectionId: "C.2.7", question: "What is the maximum number of usable Secondary Surveillance Radar (SSR) transponder codes?", optionA: "4096", optionB: "1000", optionC: "3600", optionD: "760", correctAnswer: "a", explanation: "Four octal digits give 8⁴ = 4096 Mode A codes.", difficulty: "medium" },
  { id: "IRRN-170", sectionId: "C.2.8", question: "In general a GPS-receiver is able to determine:", optionA: "only a three dimensional position and a time reference", optionB: "only a three dimensional position and groundspeed", optionC: "only a three dimensional position", optionD: "a three dimensional position, groundspeed and a precise time reference", correctAnswer: "d", explanation: "A GPS receiver solves for 3D position, ground speed (from successive fixes/Doppler) and precise time.", difficulty: "medium" },
  { id: "IRRN-171", sectionId: "C.2.8", question: "Assume that one of the satellites used by a GPS-receiver is faulty. When the signals of 5 satellites are received (including the faulty one) the RAIM software in the receiver:", optionA: "is unable to detect and identify the faulty satellite", optionB: "is able to detect that one of the satellites is faulty but is unable to identify the faulty one", optionC: "is able to detect that one of the satellites is faulty and is able to identify and isolate the faulty one", optionD: "is NOT active, as the software needs at least 8 satellites to function correctly", correctAnswer: "b", explanation: "RAIM needs 5 satellites to detect a fault and 6 to identify/exclude it, so with 5 it can only detect.", difficulty: "hard" },
  { id: "IRRN-172", sectionId: "C.2.8", question: "ICAO Annex 10 Volume I specifies the requirements for GNSS navigation services. With regard to GPS and GLONASS they:", optionA: "Are two separate systems but only GPS is capable of providing approved position data", optionB: "can both be used in a suitably equipped aircraft as the systems are compatible and their functions are interoperable", optionC: "Can both be used, but because their information is NOT compatible an aircraft CANNOT use both systems", optionD: "Are two separate systems and only GPS is covered by EU regulations so only that service can be used by European Operations", correctAnswer: "b", explanation: "GPS and GLONASS are interoperable and can both be used in a suitably equipped aircraft.", difficulty: "medium" },
  { id: "IRRN-173", sectionId: "C.2.8", question: "Concerning the NAVSTAR/GPS satellite navigation system, what is the meaning of the term Receiver Autonomous Integrity Monitoring (RAIM)?", optionA: "it is a technique by which a receiver ensures the integrity of the navigation information", optionB: "it is the ability of the GPS satellites to check the integrity of the data transmitted by the monitoring stations of the ground segment", optionC: "It is a technique whereby the receivers of the world-wide distributed monitor stations (ground segment) automatically determines the integrity of the navigation message", optionD: "It is a method whereby a receiver ensures the integrity of the Pseudo Random Noise (PRN) code transmitted by the satellites", correctAnswer: "a", explanation: "RAIM is a receiver-based technique using redundant satellites to verify navigation integrity.", difficulty: "medium" },
  { id: "IRRN-174", sectionId: "C.2.8", question: "Which of the following lists all the parameters that can be determined by a GPS receiver tracking signals from 4 different satellites?", optionA: "Latitude, longitude and altitude", optionB: "Latitude and longitude", optionC: "Latitude, longitude, altitude and time", optionD: "Latitude, longitude and time", correctAnswer: "c", explanation: "Four satellites solve four unknowns: latitude, longitude, altitude and receiver clock time.", difficulty: "medium" },
  { id: "IRRN-175", sectionId: "C.2.8", question: "Receiver Autonomous Integrity Monitoring (RAIM) is a method used to ensure integrity of the position shown by the GPS receiver. This is achieved by using the 3D position and time data from:", optionA: "Any number of visible satellites beyond 4 to create several independent positions which should agree", optionB: "More than one GPS receiver and compare these to eliminate the receiver that shows incorrect data", optionC: "Multiple aircraft systems and compare to the GPS 3D position and time data to check for consistency", optionD: "A database in the GPS receiver and compare to the 3D position and time data derived from 4 satellites", correctAnswer: "a", explanation: "RAIM uses extra (beyond 4) satellites to form redundant position solutions that should agree.", difficulty: "medium" },
  { id: "IRRN-176", sectionId: "C.2.8", question: "Each range calculated by the GPS-receiver defines:", optionA: "A circle with its centre at the satellite", optionB: "A sphere with its centre at the satellite", optionC: "A circle with its centre at the receiver", optionD: "A sphere with its centre at the receiver", correctAnswer: "b", explanation: "A single range measurement places the receiver on a sphere centred on that satellite.", difficulty: "medium" },
  { id: "IRRN-177", sectionId: "C.2.8", question: "How is range measured at GNSS (Global Navigation Satellite System) receivers?", optionA: "Sphere with the satellite at the center", optionB: "Ellipse with the user at the center", optionC: "Ellipse with the satellite at the center", optionD: "Sphere with the user at the center", correctAnswer: "a", explanation: "Each pseudorange defines a sphere centred on the transmitting satellite.", difficulty: "medium" },
  { id: "IRRN-178", sectionId: "C.2.8", question: "In the NAVSTAR/GPS system, what is the function of the Doppler principle:", optionA: "optimizing GPS accuracy in mountainous terrain", optionB: "coordinating precise timing signals between GPS satellites", optionC: "to determine the position of satellites in orbit", optionD: "to measure the ground speed of aircraft", correctAnswer: "d", explanation: "The Doppler shift of the carrier is used to derive the aircraft's ground speed.", difficulty: "medium" },
  { id: "IRRN-179", sectionId: "C.2.8", question: "The doppler frequency shift of the received GPS carrier frequency may be used to:", optionA: "correct the calculated position for a change in receiver clock error", optionB: "correct the calculated position for frequency shifts", optionC: "calculate the ground speed of the aircraft", optionD: "calculate the height of the aircraft more accurately", correctAnswer: "c", explanation: "The carrier Doppler shift gives the rate of change of range, from which ground speed is computed.", difficulty: "medium" },
  { id: "IRRN-180", sectionId: "C.2.8", question: "Almanac data stored in the receiver of the satellite navigation system NAVSTAR/GPS is used for the:", optionA: "correction of receiver clock error", optionB: "assignment of received PRN-codes (Pseudo Random Noise) to the appropriate satellite", optionC: "recognition whether Selective Availability (SA is operative)", optionD: "fast identification of received signals coming from visible satellites", correctAnswer: "d", explanation: "Almanac data (coarse orbit/status of all satellites) lets the receiver quickly work out which satellites are visible and acquire them.", difficulty: "medium" },
  { id: "IRRN-181", sectionId: "C.2.8", question: "An all in view satellite navigation receiver is one which:", optionA: "selects and tracks all (in view) satellites and selects the best four", optionB: "tracks selected satellites", optionC: "tracks the closest satellites", optionD: "monitors all 24 satellites", correctAnswer: "a", explanation: "An all-in-view receiver tracks every visible satellite and uses the best geometry (best four+).", difficulty: "medium" },
  { id: "IRRN-182", sectionId: "C.2.8", question: "In relation to the satellite navigation system NAVSTAR/GPS, \"All in View\" is a term used when a receiver:", optionA: "is receiving and tracking the signals of all 24 operational satellites simultaneously", optionB: "is receiving the signals of all visible satellites but tracking only those of the 4 with the best geometric coverage", optionC: "is tracking more than the required 4 satellites and can instantly replace any lost signal with another already being monitored", optionD: "requires the signals of all visible satellites for navigation purposes", correctAnswer: "c", explanation: "All-in-view tracks more than four satellites so a lost signal is immediately replaced by another already monitored.", difficulty: "medium" },
  { id: "IRRN-183", sectionId: "C.2.8", question: "In the NAVSTAR/GPS satellite navigation system, receiver clock error:", optionA: "is corrected by using signals from four satellites", optionB: "can be minimized by synchronization of the receiver clock with the satellite clocks", optionC: "is negligible small because of the great accuracy the atomic clocks installed in the satellites", optionD: "is the biggest part of the total error, it cannot be corrected", correctAnswer: "a", explanation: "The fourth satellite provides the extra equation that solves the receiver clock error.", difficulty: "medium" },
  { id: "IRRN-184", sectionId: "C.2.8", question: "What datum is used for the Minimum Descent Altitude (MDA) on a non-precision approach when using the NAVSTAR/GPS satellite navigation system?", optionA: "Barometric altitude", optionB: "If using Differential-GPS (D-GPS) the altitude obtained from the D-GPS, otherwise barometric altitude", optionC: "GPS altitude", optionD: "Radar altitude", correctAnswer: "a", explanation: "On a GPS non-precision approach the MDA is flown against barometric altitude.", difficulty: "medium" },
  { id: "IRRN-185", sectionId: "C.2.8", question: "The GPS satellite navigation system operates by:", optionA: "measuring the time for the signal to reach the receiver", optionB: "measuring the time for the signal to travel to the receiver and back", optionC: "measuring the phase of the incoming signal", optionD: "phase comparison", correctAnswer: "a", explanation: "GPS is one-way ranging: it measures the transit time of the signal from satellite to receiver.", difficulty: "medium" },
  { id: "IRRN-186", sectionId: "C.2.8", question: "One of the tasks of the control segment of the satellite navigation system NAVSTAR/GPS is to:", optionA: "grant and monitor user authorizations", optionB: "manipulate the signals of selected satellites to reduce the precision of the position fix (Selective Availability SA)", optionC: "manufacture and launch the satellites", optionD: "monitor the status of the satellites", correctAnswer: "d", explanation: "The control segment monitors satellite health/status and uploads corrections (SA was discontinued in 2000).", difficulty: "medium" },
  { id: "IRRN-187", sectionId: "C.2.8", question: "The preferred GNSS receiver for airborne application is:", optionA: "fast multiplex", optionB: "sequential", optionC: "multiplex", optionD: "multi-channel", correctAnswer: "d", explanation: "A multi-channel receiver tracks several satellites simultaneously and is preferred for airborne use.", difficulty: "medium" },
  { id: "IRRN-188", sectionId: "C.2.8", question: "NAVSTAR GPS receiver clock error is removed by:", optionA: "synchronization with the satellite clocks on initialization", optionB: "regular auto-synchronization with the satellite clocks", optionC: "adjusting the pseudo-ranges to determine the error", optionD: "having an appropriate atomic time standard within the receiver", correctAnswer: "c", explanation: "The receiver solves the clock bias by adjusting the pseudo-ranges (the fourth-satellite equation), so no atomic clock is needed.", difficulty: "medium" },
  { id: "IRRN-189", sectionId: "C.2.8", question: "The main task of the user segment (receiver) of the satellite navigation system NAVSTAR/GPS is to:", optionA: "select appropriate satellites automatically, to track the signals and to measure the time taken by signals from the satellites to reach the receiver", optionB: "monitor the orbital planes of the satellites", optionC: "transmit signals which, from the time taken, are used to determine the distance to the satellite", optionD: "to monitor the status of the satellites, determine their positions and to measure the time", correctAnswer: "a", explanation: "The user segment selects and tracks satellites and measures signal transit time to compute pseudoranges.", difficulty: "medium" },
  { id: "IRRN-190", sectionId: "C.2.8", question: "What type of satellite navigation system NAVSTAR/GPS receiver is most suitable for use on board an aircraft?", optionA: "Any handheld type", optionB: "Multichannel", optionC: "Sequential", optionD: "Multiplex", correctAnswer: "b", explanation: "A multichannel receiver, tracking all satellites simultaneously, is best for airborne use.", difficulty: "medium" },
  { id: "IRRN-191", sectionId: "C.2.8", question: "How many GPS satellites must be in view of a receiver in order to resolve clock bias?", optionA: "4", optionB: "1", optionC: "3", optionD: "2", correctAnswer: "c", explanation: "With a known/aided altitude, three satellites resolve the two horizontal unknowns plus clock bias.", difficulty: "hard" },
  { id: "IRRN-192", sectionId: "C.2.8", question: "The function of the receiver in the GNSS user segment is to:", optionA: "Interrogate the satellites to determine range", optionB: "Determine position and assess the accuracy of that position", optionC: "Track the satellites to calculate range", optionD: "Track the satellites to calculate time", correctAnswer: "c", explanation: "The user-segment receiver tracks the satellites and computes pseudoranges (range) to fix position.", difficulty: "medium" },
  { id: "IRRN-193", sectionId: "C.2.8", question: "The task of the control segment is to:", optionA: "all of the above", optionB: "monitor the SV ephemeris and clock", optionC: "determine availability to users", optionD: "apply selective availability", correctAnswer: "b", explanation: "The control segment monitors each space vehicle's ephemeris and clock and uploads corrections.", difficulty: "medium" },
  { id: "IRRN-194", sectionId: "C.2.8", question: "The aircraft autonomous integrity monitoring (AIM) function of an aircraft receiver is performed using:", optionA: "satellite signals only", optionB: "differential GPS", optionC: "information from other onboard navigation equipment in addition to satellite signals", optionD: "a ground relay station", correctAnswer: "c", explanation: "AAIM augments satellite integrity checking with other on-board nav sensors (IRS, baro).", difficulty: "medium" },
  { id: "IRRN-195", sectionId: "C.2.8", question: "One of the tasks of the GPS control segment is:", optionA: "to control continuously the position and the motion of GPS-satellites", optionB: "to calculate and transmit differential corrections to users which are able to receive Wide Area Differential GPS systems", optionC: "to determine and send new ephemeris and new satellite clock error data to the GPS-satellites", optionD: "to regulate the transmitted power by the satellites", correctAnswer: "c", explanation: "The control segment computes and uploads fresh ephemeris and clock-correction data to the satellites.", difficulty: "medium" },
  { id: "IRRN-196", sectionId: "C.2.8", question: "The system capable of measuring on the ground the signal errors transmitted by GNSS satellites and relay the measured errors to the user for correction is?", optionA: "ABAS", optionB: "TBAS", optionC: "GBAS", optionD: "SBAS", correctAnswer: "c", explanation: "A Ground-Based Augmentation System (GBAS) measures GNSS errors at a ground station and transmits corrections locally.", difficulty: "medium" },
  { id: "IRRN-197", sectionId: "C.2.8", question: "RAIM alert means:", optionA: "GNSS position information is not accurate enough for flight", optionB: "the ILS or VOR transmitter unit has detected a fault in its self-monitoring system", optionC: "the GNSS receiver's ability to detect a failed satellite is lost", optionD: "RNAV (GNSS) instrument approach procedure may be conducted only at an aerodrome where surveillance radar service is provided", correctAnswer: "c", explanation: "A RAIM alert means insufficient satellites/geometry so the receiver can no longer guarantee fault detection.", difficulty: "medium" },
  { id: "IRRN-198", sectionId: "C.2.8", question: "Which of the following statements about the accuracy that can be obtained with the LAAS (local area augmentation system) of the satellite navigation system NAVSTAR/GPS is correct?", optionA: "The increase in accuracy of position fixes is independent of the aircraft position in relation to the LAAS ground reference station", optionB: "The closer the receiver is to a LAAS ground reference station, the more accurate is the aircraft position fix", optionC: "A LAAS corrects the position of the aircraft by relaying the information via a geo-stationary satellite", optionD: "A LAAS cannot correct for satellite timing and orbital position error", correctAnswer: "b", explanation: "LAAS/GBAS corrections are most valid near the reference station and degrade with distance from it.", difficulty: "medium" },
  { id: "IRRN-199", sectionId: "C.2.8", question: "The geometric shape of the reference system for the satellite navigation system NAVSTAR GPS, defined as WGS 84, is:", optionA: "a sphere", optionB: "a mathematical model that describes the exact shape of the earth", optionC: "a geoid", optionD: "an ellipsoid", correctAnswer: "d", explanation: "WGS 84 models the earth as a reference ellipsoid.", difficulty: "medium" },
  { id: "IRRN-200", sectionId: "C.2.8", question: "What is the minimum number of NAVSTAR/GPS satellites required to produce an accurate independent 3-D position fix?", optionA: "24", optionB: "3", optionC: "4", optionD: "5", correctAnswer: "c", explanation: "Four satellites are needed to solve latitude, longitude, altitude and clock error.", difficulty: "medium" },
  { id: "IRRN-201", sectionId: "C.2.8", question: "The WGS 84 model of the earth is:", optionA: "A mathematical model that describes the exact shape of the earth", optionB: "A sphere", optionC: "A geoid", optionD: "An ellipsoid", correctAnswer: "d", explanation: "WGS 84 represents the earth as a reference ellipsoid.", difficulty: "medium" },
  { id: "IRRN-202", sectionId: "C.2.8", question: "Assume that one of the satellites used by an aircraft's GPS receiver is faulty and that the PDOP (position dilution of precision) has a relatively low value. The receiver receives the signals of 6 satellites, including the faulty one. The receiver's RAIM software:", optionA: "will detect that one of the satellites is faulty and then identify the faulty one and isolate it", optionB: "Cannot detect and identify the faulty satellite", optionC: "will detect the faulty satellite, but will be unable to isolate it as RAIM needs at least 7 satellites for full functionality", optionD: "will alert the pilot about the faulty satellite, but it is unable to identify it", correctAnswer: "a", explanation: "With 6 satellites (and good geometry) RAIM can both detect and identify/exclude the faulty satellite (fault detection and exclusion).", difficulty: "hard" },
  { id: "IRRN-203", sectionId: "C.2.3", question: "Which statement is true about the use of the Doppler effect in a Doppler VOR?", optionA: "The Doppler effect is used to create a signal which is received by the aircraft's VOR receiver as an amplitude modulated signal", optionB: "By using the Doppler effect it is also possible to determine the aircraft's approach speed to the VOR", optionC: "The Doppler effect is used to create a signal which is received by the aircraft's VOR receiver as a frequency modulated signal", optionD: "By using the Doppler effect it is possible to determine the range of the aircraft from the VOR station more accurately", correctAnswer: "c", explanation: "In a Doppler VOR the moving (commutated) antenna creates the 30 Hz variable signal as an FM signal at the receiver (the reverse of a conventional VOR).", difficulty: "hard" },
];

export const IR_RADIONAV_COUNT = IR_RADIONAV_QUESTIONS.length;

export function getIRRadioNavQuestionsBySection(sectionId: string): AirLawQuestion[] {
  return IR_RADIONAV_QUESTIONS.filter((q) => q.sectionId === sectionId);
}
